local ADDON, ns = ...

ns.MountTips = {
    [264] = { year = 2026, -- Blue Proto-Drake
        text = "Skadi only comes down after his drake {npc:26893|Grauf} is shot down: during the event, collect three harpoons ({item:37372|Harpoon}) and fire them from the Harpoon Launchers as Grauf flies past. After three hits Skadi lands and the fight begins. Heroic is locked once a day per character, so players run it every day on several characters." },
    [265] = { year = 2026, -- Time-Lost Proto-Drake
        text = "It shares its spawn points, flight paths and timer with {npc:32630|Vyragosa}, a much more common rare: only one of the two is up at a time, and either can be the one that appears. After one of them dies, the next takes hours to show up (players report up to about 8 hours). Both appear at four places and then fly away: near 31.5, 70.0, near 35.0, 76.5, near 51.1, 71.2 and near 52.3, 35.0." },
    [286] = { year = 2025, -- Doomwalker's mounts
        own = "A very rare drop of Doomwalker, and also of the anniversary Archavon in Tanaris (2024, 2025). At any time of year: any of the four bosses of Vault of Archavon, in {map:123|Wintergrasp}, once a week per character. The Alliance and the Horde versions are learned for both factions.",
        text = "Only during WoW's anniversary event, in November. {npc:167749|Doomwalker} is a world boss: since 2024 it stands south of the Caverns of Time, in {map:71|Tanaris}. It needs a group: join the raid that gathers there or one listed in the group finder. Loot is once per day per character, so each alt has its own chance (2024 and 2025)." },
    [287] = { year = 2025, -- Doomwalker's mounts
        own = "A very rare drop of Doomwalker, and also of the anniversary Archavon in Tanaris (2024, 2025). At any time of year: any of the four bosses of Vault of Archavon, in {map:123|Wintergrasp}, once a week per character. The Alliance and the Horde versions are learned for both factions.",
        text = "Only during WoW's anniversary event, in November. {npc:167749|Doomwalker} is a world boss: since 2024 it stands south of the Caverns of Time, in {map:71|Tanaris}. It needs a group: join the raid that gathers there or one listed in the group finder. Loot is once per day per character, so each alt has its own chance (2024 and 2025)." },
    [293] = { year = 2025, -- Doomwalker's mounts
        own = "Since 2024 it is no longer a sure drop. During the 2024 event, {npc:158061|Historian Ma'di} also sold it for 5,000 {currency:1166|Timewarped Badges}.",
        text = "Only during WoW's anniversary event, in November. {npc:167749|Doomwalker} is a world boss: since 2024 it stands south of the Caverns of Time, in {map:71|Tanaris}. It needs a group: join the raid that gathers there or one listed in the group finder. Loot is once per day per character, so each alt has its own chance (2024 and 2025)." },
    [312] = { year = 2026, -- Sea Turtle
        text = "Only fishing pools give it, never open water: the pools of {map:113|Northrend}, of the Cataclysm zones and of {map:424|Pandaria}, and the Shipwreck Debris around {map:407|Darkmoon Island} during the Darkmoon Faire. The chance per catch is tiny. In your Draenor garrison there is another way: a {item:112633|Frostdeep Minnow} fished there and thrown into the garrison pond summons a Cavedweller ({npc:81171|Frostdeep Cavedweller} for the Horde, {npc:85715|Lunarfall Cavedweller} for the Alliance), which drops it at about 0.2% per kill. Every member of a group loots each Cavedweller, so players farm them in raid groups." },
    [393] = { year = 2026, -- Phosphorescent Stone Drake
        text = "{npc:50062|Aeonaxx} starts out friendly, flying in tight circles high around the Temple of Earth, at about the height of the entrance to the Stonecore. Click him to ride him: he turns hostile and you fight from his back, and you have to kill the whelps he summons, or they overwhelm you. {npc:3868|Blood Seeker}, a bat, shares his spawn and can appear in his place." },
    [400] = { year = 2024, -- Grey Riding Camel
        text = "The way to {npc:50245|Dormus} is a {npc:50409|Mysterious Camel Figurine} in {map:249|Uldum}. The figurines appear only in the Cataclysm version of Uldum ({npc:162419|Zidormi} switches it), at many places across the zone, and most of them just crumble to dust; the real one teleports you to the Steam Pools in {map:69|Feralas}, where Dormus waits. They cannot be targeted, but the Friendly NPC Nameplates option shows them from afar. After a figurine is clicked, the next appears 2 to 8 hours later, and War Mode on and off each have their own." },
    [401] = { year = 2021, -- Dark Phoenix
        text = "Sold by the guild vendors to a character Exalted with a guild that has {achievement:4988|Guild Glory of the Cataclysm Raider}. Joining a guild that already has it works, but the reputation with a new guild starts over. Once learnt, the mount is yours whatever guild you are in." },
    [419] = { year = 2024, -- Amani Battle Bear
        text = "It is the reward of a timed event in {map:333|Zul'Aman}: inside, take {quest:29217|The Captive Scouts} by the closed gate and open the gate with the gong. A timer starts: kill {npc:23574|Akil'zon}, {npc:23576|Nalorakk}, {npc:23578|Jan'alai} and {npc:23577|Halazzi} and free the captive by each one before it runs out. The mount is in the bag of the last captive freed, so leave Halazzi for last: his captive, {npc:52945|Kasha}, then reveals Kasha's Bag." },
    [420] = { year = 2021, -- Subdued Seahorse
        text = "Old guides that say {npc:50005|Poseidus} appears once or twice a week are out of date: his timer was cut, and he now comes back some hours after each kill, at one of his places in the {map:205|Shimmering Expanse} or the {map:204|Abyssal Depths}. A Class Trial character does not get the reins from him." },
    [439] = { year = 2026, -- Tyrael's Charger
        text = "The {npc:205490|Treasure Goblins} dropped it only in the 2023 Greedy Emissary event; in the 2025 edition they did not. It comes back from time to time to the Trading Post, for 900 {currency:2032|Trader's Tender} (July 2023 and September 2026)." },
    [445] = { year = 2025, -- Experiment 12-B
        text = "The mount does not drop from {npc:55294|Ultraxion} himself: it is in the Lesser Cache of the Aspects that appears after the fight. It can also come in the {item:208095|Cache of Timewarped Treasures} given by the weekly quest of the Cataclysm Timewalking raid, at about 0.5% per cache." },
    [473] = { year = 2024, -- Heavenly Onyx Cloud Serpent
        text = "The {npc:60491|Sha of Anger} comes back quickly, always at the same place, but each character can loot him only once a week, so players kill him with many characters. After the kill you can also use Bonus Loot with an {currency:697|Elder Charm of Good Fortune}, sold by {npc:64607|Commander Lo Ping} in {map:388|Townlong Steppes} for 20 {currency:738|Lesser Charm of Good Fortune}, which drop from the creatures of the {map:554|Timeless Isle}." },
    [515] = { year = 2024, -- Son of Galleon
        text = "{npc:62346|Galleon} comes back quickly, always at the same place, but each character can loot him only once a week, so players kill him with many characters. After the kill you can also use Bonus Loot with an {currency:697|Elder Charm of Good Fortune}, sold by {npc:64607|Commander Lo Ping} in {map:388|Townlong Steppes} for 20 {currency:738|Lesser Charm of Good Fortune}, which drop from the creatures of the {map:554|Timeless Isle}." },
    [533] = { year = 2025, -- Cobalt Primordial Direhorn
        text = "{npc:69161|Oondasta} comes back quickly, always at the same place, but each character can loot him only once a week, so players kill him with many characters. Hunters can tame him, and then he is gone until the next spawn. After the kill you can also use Bonus Loot with a {currency:752|Mogu Rune of Fate}, sold by {npc:73305|Mistweaver Ai} on the {map:554|Timeless Isle} for 1,000 {currency:777|Timeless Coin}." },
    [534] = { year = 2024, -- Primordial Direhorns of the Zandalari Warbringer
        own = "Only a Warbringer riding an amber direhorn drops it.",
        text = "The {npc:69769|Zandalari Warbringer} appears at five places in Pandaria, each with its own timer, riding a direhorn of one colour, and only a mount of that colour can drop from him. There is no lockout: every kill is a new chance, so players fly from place to place. In {map:418|Krasarang Wilds} only the slate one appears." },
    [535] = { year = 2024, -- Primordial Direhorns of the Zandalari Warbringer
        own = "Only a Warbringer riding a slate direhorn drops it.",
        text = "The {npc:69769|Zandalari Warbringer} appears at five places in Pandaria, each with its own timer, riding a direhorn of one colour, and only a mount of that colour can drop from him. There is no lockout: every kill is a new chance, so players fly from place to place. In {map:418|Krasarang Wilds} only the slate one appears." },
    [536] = { year = 2024, -- Primordial Direhorns of the Zandalari Warbringer
        own = "Only a Warbringer riding a jade direhorn drops it.",
        text = "The {npc:69769|Zandalari Warbringer} appears at five places in Pandaria, each with its own timer, riding a direhorn of one colour, and only a mount of that colour can drop from him. There is no lockout: every kill is a new chance, so players fly from place to place. In {map:418|Krasarang Wilds} only the slate one appears." },
    [542] = { year = 2025, -- Thundering Cobalt Cloud Serpent
        text = "{npc:69099|Nalak} comes back quickly in the sky in front of the Throne of Thunder, but each character can loot him only once a week, so players kill him with many characters. After the kill you can also use Bonus Loot with a {currency:752|Mogu Rune of Fate}, sold by {npc:73305|Mistweaver Ai} on the {map:554|Timeless Isle} for 1,000 {currency:777|Timeless Coin}." },
    [561] = { year = 2025, -- Thundering Onyx Cloud Serpent
        text = "There is no lockout: the reins can drop on every kill of {npc:73167|Huolon}, many times a day. When he appears he cannot be attacked for 1 minute; wait for that to end before you pull him." },
    [611] = { year = 2025, -- Rattling Iron Cage (Tundra Icehoof, Armored Razorback, Warsong Direfang)
        text = "It comes in a {item:128025|Rattling Iron Cage}, which any of the four big rares of {map:534|Tanaan Jungle} can drop. The cage gives one of its three mounts at random, and a mount you already have can come again. Each rare gives loot once a day per character. When a rare appears, its yell shows in the chat of the whole zone: that is the moment to fly to it." },
    [612] = { year = 2026, -- Bloodhoof Bull
        text = "The rare gives the mount to everyone who tags it. A player reported in 2026 that it only appeared after finishing the {map:550|Nagrand} quest {quest:35169|And Justice for Thrall}: if you never see it, move the zone's story forward first." },
    [622] = { year = 2025, -- Rattling Iron Cage (Tundra Icehoof, Armored Razorback, Warsong Direfang)
        text = "It comes in a {item:128025|Rattling Iron Cage}, which any of the four big rares of {map:534|Tanaan Jungle} can drop. The cage gives one of its three mounts at random, and a mount you already have can come again. Each rare gives loot once a day per character. When a rare appears, its yell shows in the chat of the whole zone: that is the moment to fly to it." },
    [634] = { year = 2026, -- Solar Spirehawk
        text = "{npc:83746|Rukhmar} is a world boss that comes back about 15 minutes after each kill, but each character can loot it only once a week, so players farm it with many characters. It appears next to Skyreach, at about 37, 39 in {map:542|Spires of Arak}, and flies around the zone until someone pulls it. The mount also turns up now and then at the Black Market Auction House." },
    [643] = { year = 2025, -- Rattling Iron Cage (Tundra Icehoof, Armored Razorback, Warsong Direfang)
        text = "It comes in a {item:128025|Rattling Iron Cage}, which any of the four big rares of {map:534|Tanaan Jungle} can drop. The cage gives one of its three mounts at random, and a mount you already have can come again. Each rare gives loot once a day per character. When a rare appears, its yell shows in the chat of the whole zone: that is the moment to fly to it." },
    [655] = { year = 2026, -- Sunhide Gronnling
        text = "The rare gives the mount to everyone who tags it, and it takes many hours to come back, so players wait for it together in groups listed in Premade Groups. The old rule that it takes at least 48 hours no longer holds, by a 2026 report." },
    [657] = { year = 2022, -- Garn Nighthowl
        text = "Only one copy drops per kill, for a single player of the group. The item is not bound, so it can also be bought at the Auction House. {npc:81001|Nok-Karosh} comes back within the hour after a kill." },
    [682] = { year = 2021, -- Voidtalon of the Dark Star
        text = "The mount is in an egg on the other side of the Edge of Reality, a portal, and the egg always gives it. The portal appears rarely, at one of the marked places of six zones of Draenor, stays for some minutes and takes only the first player who clicks it. Each zone keeps its own timer: players leave one character in each zone and go round the places." },
    [802] = { year = 2018, -- Long-Forgotten Hippogryph
        text = "Five Ephemeral Crystals appear at the same time at random spots of {map:630|Azsuna}, many of them inside caves. Touching the first one starts 8 hours to touch the other four; dying loses the count. Other players are after the same crystals, and when somebody finishes they all vanish until the next round." },
    [803] = { year = 2022, -- Covenant mounts of the rares of Korthia
        own = "Only for a Venthyr character. {npc:179985|Stygian Stonecrusher} drops a crystal, an item that starts a quest: the quest gives the mount.",
        text = "Each character has one try a day at each rare of {map:1961|Korthia}. What the rare drops is not the mount, but what leads to it. Players with low renown got them." },
    [838] = { year = 2026, -- Fathom Dweller
        text = "Start with {npc:102695|Drak'thul} at 37.2, 71.7 in {map:646|Broken Shore}: talk to him until he tells you to go away. Take the {item:139783|Weathered Relic} from a dirt pile at the back of the cave at 58.5, 54 (relog if rocks block the way), bring it back and talk to him again, several times, until he has nothing left to say. Then click the ten Hungering Orbs hidden in caves across the Broken Isles, strictly in order; the tenth is on his table. The list of places is long: it is in the guides on the mount's Wowhead page. After that, the world quest of {npc:111573|Kosumoth the Hungering} appears in {map:790|Eye of Azshara} (the open zone, not the dungeon); its reward is sometimes the mount and sometimes the pet {item:140261|Hungering Claw}." },
    [928] = { year = 2026, -- Dune Scavenger
        text = "Any creature of {map:864|Vol'dun} can drop it, with a very small chance per kill: the rares marked on the map are only some of them. It does not bind when looted, so it can also be bought at the Auction House." },
    [931] = { year = 2026, -- Netherlord's Accursed Wrathsteed
        text = "Only a warlock who has already finished the class mount quest {quest:46243|The Wrathsteed of Xoroth} gets it: before that, the rare does not drop it, and killing it again the same day does not help, because it gives loot once a day. With the quest done, players report getting it on the first kill. {npc:119629|Lord Hel'nurath} appears at no fixed time and stays up for a while. Only warlocks can ride it." },
    [947] = { year = 2026, -- Riddler's Mind-Worm
        text = "Read eight pages in this order; each opens the next. 1: bookshelf on the ground floor of the Legerdemain Lounge, {map:627|Dalaran}. 2: table by the moonwell, {map:47|Duskwood} 49.1, 33.9. 3: Firelands raid, at the back left of {npc:52409|Ragnaros}'s platform. 4: {map:249|Uldum} 70.5, 78.0; first talk to {npc:162419|Zidormi} in Ramkahen to see the old Uldum, or the page is not there. 5: Siege of Orgrimmar raid, south-west corner of the {npc:71734|Sha of Pride}'s room. 6: Well of Eternity dungeon, at the stairs near 75.4, 65.4 of its map. 7: {map:379|Kun-Lai Summit} 34.6, 50.9, between the paws of the tiger statue. 8: Uldum 76.4, 53.6, at the base of the statue. Then open the chest at the marker in {map:52|Westfall}. Pages already read are kept across resets." },
    [955] = { year = 2025, -- Argus rares (Vile Fiend, Maddened Chaosrunner, Lambent Mana Ray, Crimson Slavermaw, Acid Belcher, Biletooth Gnasher)
        own = "{npc:127288|Houndmaster Kerrax} is inside a cave; the entrance is at 63.1, 25.2 in {map:885|Antoran Wastes}.",
        text = "Each of these Argus rares gives its loot once a day per character, and they are not all out every day: they take turns. The day the rare's world quest is up is the day to farm it, and players then kill it with several characters." },
    [956] = { year = 2026, -- Leaping Veinseeker
        text = "Any creature of {map:863|Nazmir} can drop it, with a very small chance per kill: the rare marked on the map is only one of them. Players farm the trolls of Torga's Rest, around 59, 22. It does not bind when looted, so it can also be bought at the Auction House." },
    [961] = { year = 2026, -- Lucid Nightmare
        text = "It starts in {map:627|Dalaran}, with a note on the upper floor of the shop at 50, 56. Then, in order: in Ulduar, past {npc:33293|XT-002 Deconstructor}, a lever in the room's north-west corner and a floor of lights to draw as a gear; in Ahn'Qiraj, beside {npc:15727|C'Thun}'s room, a match-three minigame; in {map:207|Deepholm}, a fissure in the Crumbling Depths cave (63.8, 22.5) and, below it, a chair to examine wearing a {item:10025|Shadoweave Mask} (buy it first); in Gnomeregan, ten consoles set to 1222176597; {map:641|Val'sharah} 66, 36.5, an untangling minigame; {map:379|Kun-Lai Summit} 53.4, 49, the Endless Halls maze, the hardest part: take each colour's orb to the rune of that colour, five times. The reward is in the crypt behind Karazhan. Each note leads to the next; the full guide is long." },
    [970] = { year = 2025, -- Argus rares (Vile Fiend, Maddened Chaosrunner, Lambent Mana Ray, Crimson Slavermaw, Acid Belcher, Biletooth Gnasher)
        text = "Each of these Argus rares gives its loot once a day per character, and they are not all out every day: they take turns. The day the rare's world quest is up is the day to farm it, and players then kill it with several characters." },
    [973] = { year = 2025, -- Argus rares (Vile Fiend, Maddened Chaosrunner, Lambent Mana Ray, Crimson Slavermaw, Acid Belcher, Biletooth Gnasher)
        text = "Each of these Argus rares gives its loot once a day per character, and they are not all out every day: they take turns. The day the rare's world quest is up is the day to farm it, and players then kill it with several characters." },
    [979] = { year = 2025, -- Argus rares (Vile Fiend, Maddened Chaosrunner, Lambent Mana Ray, Crimson Slavermaw, Acid Belcher, Biletooth Gnasher)
        text = "Each of these Argus rares gives its loot once a day per character, and they are not all out every day: they take turns. The day the rare's world quest is up is the day to farm it, and players then kill it with several characters." },
    [980] = { year = 2025, -- Argus rares (Vile Fiend, Maddened Chaosrunner, Lambent Mana Ray, Crimson Slavermaw, Acid Belcher, Biletooth Gnasher)
        text = "Each of these Argus rares gives its loot once a day per character, and they are not all out every day: they take turns. The day the rare's world quest is up is the day to farm it, and players then kill it with several characters." },
    [981] = { year = 2025, -- Argus rares (Vile Fiend, Maddened Chaosrunner, Lambent Mana Ray, Crimson Slavermaw, Acid Belcher, Biletooth Gnasher)
        own = "Two rares drop it, {npc:126040|Puscilla} and {npc:126199|Vrax'thul}, each with its own daily loot.",
        text = "Each of these Argus rares gives its loot once a day per character, and they are not all out every day: they take turns. The day the rare's world quest is up is the day to farm it, and players then kill it with several characters." },
    [1019] = { year = 2026, -- Goldenmane
        text = "Any creature of {map:942|Stormsong Valley} can drop it, with a very small chance per kill: the rares marked on the map are only some of them. Players farm the Brineworks, at the north-east end of Mariner's Strand, where the creatures come back quickly. It does not bind when looted, so it can also be bought at the Auction House." },
    [1057] = { year = 2025, -- Nazjatar Blood Serpent
        text = "1. Gather 20 {item:161344|Abyssal Fragment}: a drop of creatures of Kul Tiras and Zandalar, which can be bought at the auction house.\n2. In {map:942|Stormsong Valley}, at 73.5, 23.6, there is a cave behind a waterfall with an altar at the back: join the fragments there into the {item:161345|Abhorrent Essence of the Abyss}.\n3. Enter the mine at 46.5, 36.1 and go down to the small statue at 59.4, 54.2 on the map of the mine. Use the essence there: the {npc:140474|Adherent of the Abyss} comes.\n4. Only who summoned has a chance at the mount. In 2023 a character of level 70 killed it alone." },
    [1173] = { year = 2025, -- Arathi Highlands Warfront rares
        own = "Only for the Horde: {npc:142739|Knight-Captain Aldrin} is an Alliance captain, and only Horde players can attack him.",
        text = "These rares are in the Arathi Highlands of the Warfront. Each character can loot each of them once per Warfront cycle, that is, until control of the zone passes to the other faction: killing it again before that gives nothing. The {item:158075|Heart of Azeroth} is not needed: without it you may get no Azerite, but the mount can still drop." },
    [1174] = { year = 2025, -- Arathi Highlands Warfront rares
        own = "Only for the Alliance: {npc:142741|Doomrider Helgrim} is a Horde rider, and only Alliance players can attack him. He comes back a few minutes after dying, but only the first kill of the cycle can give loot.",
        text = "These rares are in the Arathi Highlands of the Warfront. Each character can loot each of them once per Warfront cycle, that is, until control of the zone passes to the other faction: killing it again before that gives nothing. The {item:158075|Heart of Azeroth} is not needed: without it you may get no Azerite, but the mount can still drop." },
    [1180] = { year = 2025, -- Arathi Highlands Warfront rares
        text = "These rares are in the Arathi Highlands of the Warfront. Each character can loot each of them once per Warfront cycle, that is, until control of the zone passes to the other faction: killing it again before that gives nothing. The {item:158075|Heart of Azeroth} is not needed: without it you may get no Azerite, but the mount can still drop." },
    [1182] = { year = 2025, -- Arathi Highlands Warfront rares
