    [1185] = { year = 2025, -- Arathi Highlands Warfront rares
        text = "These rares are in the Arathi Highlands of the Warfront. Each character can loot each of them once per Warfront cycle, that is, until control of the zone passes to the other faction: killing it again before that gives nothing. The {item:158075|Heart of Azeroth} is not needed: without it you may get no Azerite, but the mount can still drop." },
    [1199] = { year = 2026, -- Darkshore Warfront rares
        own = "Alliance players kill {npc:149652|Agathe Wyrmwood}; Horde players kill the bear at the same place.",
        text = "These rares are in the {map:62|Darkshore} of the Warfront. Each character can loot each of them once per Warfront cycle: killing it again gives nothing until control of the zone changes. A rare of one faction's side appears only while that faction controls Darkshore, and that turn comes back about every two weeks." },
    [1200] = { year = 2026, -- Darkshore Warfront rares
        own = "{npc:148787|Alash'anir} is there for both factions, whichever controls the zone.",
        text = "These rares are in the {map:62|Darkshore} of the Warfront. Each character can loot each of them once per Warfront cycle: killing it again gives nothing until control of the zone changes. A rare of one faction's side appears only while that faction controls Darkshore, and that turn comes back about every two weeks." },
    [1201] = { year = 2026, -- Frightened Kodo
        text = "The {npc:148790|Frightened Kodo} is friendly: click it and the mount is yours, with no fight, for either faction and whoever controls the Warfront. It runs fast around the marked places, and only for about 2 minutes after a new copy of {map:62|Darkshore} opens: after a realm restart, or when you enter a copy nobody was in (the loading screen takes longer). Players use a Class Trial character on a low-population realm, with War Mode on, left at the spot and logged in again every 15 to 30 minutes." },
    [1203] = { year = 2026, -- Darkshore Warfront rares
        own = "Alliance players kill {npc:147701|Moxo the Beheader}; Horde players kill {npc:148037|Athil Dewfire}.",
        text = "These rares are in the {map:62|Darkshore} of the Warfront. Each character can loot each of them once per Warfront cycle: killing it again gives nothing until control of the zone changes. A rare of one faction's side appears only while that faction controls Darkshore, and that turn comes back about every two weeks." },
    [1205] = { year = 2026, -- Darkshore Warfront rares
        own = "Alliance players kill {npc:149655|Croz Bloodrage}; Horde players kill {npc:149663|Shadowclaw}.",
        text = "These rares are in the {map:62|Darkshore} of the Warfront. Each character can loot each of them once per Warfront cycle: killing it again gives nothing until control of the zone changes. A rare of one faction's side appears only while that faction controls Darkshore, and that turn comes back about every two weeks." },
    [1229] = { year = 2026, -- Mechagon rares
        own = "The {npc:154342|Arachnoid Harvester} of the island's alternate future drops it too. You get there with {npc:153993|Chromie}'s daily quest {quest:55816|The Other Place}, on the days she visits, or with the {item:169114|Personal Time Displacer}.",
        text = "No quest of {map:1462|Mechagon Island} is needed: characters that only flew or teleported to the island got it. Each character can loot it once a day, and the rare comes back about 15 to 35 minutes after dying. A character that hit the rare and logged off before looting gets the loot by mail." },
    [1248] = { year = 2026, -- Mechagon rares
        text = "No quest of {map:1462|Mechagon Island} is needed: characters that only flew or teleported to the island got it. Each character can loot it once a day, and the rare comes back about 15 to 35 minutes after dying. A character that hit the rare and logged off before looting gets the loot by mail." },
    [1250] = { year = 2026, -- Mollie
        text = "{npc:138794|Dunegorger Kraulok} is a world boss of {map:864|Vol'dun} that appears only while its world quest is up: one week in every six, in the rotation of Battle for Azeroth's world bosses. While it is up, it comes back about a minute after dying, so players bring one character after another. A character does not need world quests unlocked, or to see the quest, to get the loot." },
    [1257] = { year = 2025, -- Silent Glider
        text = "{map:1355|Nazjatar} has to be open to the character, through its introduction quest. {npc:152290|Soundless} takes at least 2 hours to come back after dying, often up to about 4, and appears at one of several places on top of the corals of the Coral Forest. Each character can loot it once a day." },
    [1258] = { year = 2026, -- Fabious
        text = "Do not attack him (he cannot be hurt): take a picture with him using the {item:122674|S.E.L.F.I.E. Camera MkII} toy, and the mount comes. He shows no star on the map, moves slowly around one of the marked places of {map:1355|Nazjatar}, and stays only 3 to 6 minutes, less at some places. Hours pass between appearances: reports go from 2 to 9 hours of waiting, and he was only seen in copies of the zone open for 2 hours or more. Land before using the camera, or you fall. If the mount does not come, take the picture again with all of him in the frame." },
    [1297] = { year = 2022, -- Clutch of Ha-Li
        text = "{npc:157153|Ha-Li} is only there while the assault on the {map:1530|Vale of Eternal Blossoms} is {quest:57008|Assault: The Warring Clans}, the one of the Mogu. It flies in circles high in the air east of the Ruins of Guo-Lai. Each character can loot it once a day. A character that has not started the story of patch 8.3 may not see the assault: in 2022 a player saw it after only accepting {quest:56374|A Titanic Problem}." },
    [1298] = { year = 2025, -- Hopecrusher Gargon
        text = "Only a Venthyr character can loot it: characters of other covenants can help with the kill, but get no chance at the mount. Once learned, any covenant can ride it." },
    [1304] = { year = 2026, -- Mawsworn Soulhunter
        text = "{npc:174861|Gorged Shadehound} only comes with its hunt, in the Beastwarrens of {map:1543|The Maw}: four hunts take turns there, so this one is on for three and a half days and then off for ten and a half. Kill the 6 packs of adds by the cave; the hound then runs into the cave and can be attacked. At about half health it drops to the floor below: click the chains to follow it with no fall damage. One try per character each time the hunt is on. The event has broken more than once and was working again in 04/2026; if it is stuck on your realm, look for a group on another." },
    [1306] = { year = 2021, -- Swift Gloomhoof
        text = "{npc:168135|Night Mare} is only seen with a {item:178675|Dream Catcher}, made in three steps:\n1. Loot the {item:181243|Broken Soulweb} by a broken cart on a platform at 19.7, 63.5, west of Tirna Scithe; get there with a glider or a {item:174042|Pinch of Faerie Dust}.\n2. Dismounted, give it with 10 {item:173204|Lightless Silk} to {npc:165704|Elder Gwenna} at 50.4, 33.0; she is only there after {quest:57871|Outplayed}.\n3. Take the {item:181242|Repaired Soulweb} to {npc:160262|Ysera}, in the Heart of the Forest; other covenants talk to the guards at the door, and she comes out.\nUse the Dream Catcher in Dreamshrine Basin: the effect lasts 5 minutes and is renewed by using it again. Everyone in the group needs one of their own." },
    [1307] = { year = 2026, -- Sundancer
        text = "First buy a {item:180445|Skystrider Glider} at the Auction House: it is used up on every try, and no other glider works. Click the Ancient Memorial at 60.0, 94.0 in {map:1533|Bastion} for Sunrider's Blessing (30 minutes). {npc:170548|Sundancer} flies a round over the area: wait above its path (the ledge at 60.9, 81.4 works), get off your mount, use the glider and land on its back. Press Soothe again and again until the button goes away: it then carries you to the memorial and drops you there. Talk to it to start the fight. The mount is sure only for whoever rode it, and only if it dies within 5 minutes of the glide." },
    [1310] = { year = 2025, -- Horrid Dredwing
        text = "Only a Venthyr character can loot it. It only comes down when a Venthyr's Anima Conductor is channeling to Wanecrypt Hill: take a {item:176397|Dredhollow Bolt} from the castle to the west, around 42.7, 73.4, to {npc:165327|Wingsmash} at 46.3, 77.8. He fires the {npc:165324|Dredterror Ballista} at it, and then it can be attacked. If Wingsmash just stands looking at the ballista, the event is stuck on that copy of the zone: joining another player's group usually takes you to one that works." },
    [1311] = { year = 2026, -- Mounts of the Mogu assault in the Vale of Eternal Blossoms
        own = "Catch the serpent with a {item:174927|Zan-Tien Lasso}, a drop of the Zan-Tien mogu of the Vale. It appears high above 26.8, 55.1, about the top of the great gate to the west, just under the {npc:152550|Great Worm From Beyond}, and flies off fast. The lasso takes 2 seconds, standing still; after the first catch it stays a few seconds, and others can catch it too.",
        text = "Only while the {map:1530|Vale of Eternal Blossoms} is under Assault: Mogu, one of the assaults that take turns there every few days; the world map shows the one that is on. If the Vale looks as it did before the war, {npc:163463|Zidormi}, at 80.5, 32.0, takes you to the present. A player reported in 2022 that, for the Vale to be in this phase, it is enough to have accepted {quest:56374|A Titanic Problem}, of the Battle for Azeroth story." },
    [1313] = { year = 2020, -- Rajani Warserpent
        text = "{npc:160711|Zhang Ku} sells it for 1 {item:174230|Pristine Cloud Serpent Scale}, and asks for no reputation. The scale is a rare drop of {npc:157162|Rei Lun}, a rare inside the Guo-Lai Halls, in the {map:1530|Vale of Eternal Blossoms}: from the entrance at 22.2, 24.6, straight ahead and down to the lowest floor. He is only there while the assault on the Vale is {quest:57008|Assault: The Warring Clans}, the one of the Mogu." },
    [1314] = { year = 2026, -- Uldum assault rares
        own = "{npc:157134|Ishak of the Four Winds} appears whichever assault Uldum has, 2 to 4 hours apart. It appears outside the tower and flies to the floating platform it circles: wait for it there.",
        text = "These rares are in the {map:1527|Uldum} of the N'Zoth assaults, from patch 8.3. Each character can loot each of them once a day." },
    [1315] = { year = 2025, -- Mail Muncher
        text = "In the Horrific Visions, clicking a mailbox calls a creature and, now and then, the {npc:160708|Mail Muncher}, which always drops the mount. No mask is needed, and the vision does not have to be finished. Players go to the first mailbox, leave the vision if it is not him and enter again; reports go from 26 to about 60 entries." },
    [1317] = { year = 2026, -- Uldum assault rares
        own = "{npc:157146|Rotfeaster} is only there while Uldum's assault is {quest:55350|Assault: Amathet Advance}, for a few days about every two weeks. It comes back 40 to 90 minutes after dying, about an hour on average.",
        text = "These rares are in the {map:1527|Uldum} of the N'Zoth assaults, from patch 8.3. Each character can loot each of them once a day." },
    [1319] = { year = 2026, -- Uldum assault rares
        own = "{npc:162147|Corpse Eater} is only there while Uldum's assault is {quest:56308|Assault: Aqir Unearthed}. It comes back 3 to 20 minutes after dying. Blizzard raised the chance in March 2020, without saying by how much.",
        text = "These rares are in the {map:1527|Uldum} of the N'Zoth assaults, from patch 8.3. Each character can loot each of them once a day." },
    [1324] = { year = 2020, -- Elusive Quickhoof
        text = "{npc:162681|Elusive Quickhoof} is a friendly alpaca that appears at one of the marked places of {map:864|Vol'dun}, stays for about 10 minutes and takes hours to come back. Buy a {item:161128|Seaside Leafy Greens Mix} beforehand and feed it: the mount is yours. It has no rare marker on the map; it walks, and it may be lying down. Several players can feed the same one, in a raid group too." },
    [1327] = { year = 2026, -- Mounts of the Mogu assault in the Vale of Eternal Blossoms
        text = "Only while the {map:1530|Vale of Eternal Blossoms} is under Assault: Mogu, one of the assaults that take turns there every few days; the world map shows the one that is on. If the Vale looks as it did before the war, {npc:163463|Zidormi}, at 80.5, 32.0, takes you to the present. A player reported in 2022 that, for the Vale to be in this phase, it is enough to have accepted {quest:56374|A Titanic Problem}, of the Battle for Azeroth story." },
    [1328] = { year = 2026, -- Mounts of the Mogu assault in the Vale of Eternal Blossoms
        text = "Only while the {map:1530|Vale of Eternal Blossoms} is under Assault: Mogu, one of the assaults that take turns there every few days; the world map shows the one that is on. If the Vale looks as it did before the war, {npc:163463|Zidormi}, at 80.5, 32.0, takes you to the present. A player reported in 2022 that, for the Vale to be in this phase, it is enough to have accepted {quest:56374|A Titanic Problem}, of the Battle for Azeroth story." },
    [1355] = { year = 2025, -- Runestags of the Queen's Conservatory
        own = "Most players who have it got it from a {item:177699|Greater Untamed Spirit} with 2 grain, one of them with the conservatory still at tier 2.",
        text = "Only for a Night Fae character. Plant a spirit in the Queen's Conservatory with {item:176832|Wildseed Root Grain} in the plots connected to it, and open the cache when it has grown: it may hold either of the two." },
    [1358] = { year = 2025, -- Runestags of the Queen's Conservatory
        own = "Players got it with 4 grain around the seed, from a {item:177699|Greater Untamed Spirit}, a {item:177700|Divine Untamed Spirit} or a {item:183704|Shifting Spirit of Knowledge}.",
        text = "Only for a Night Fae character. Plant a spirit in the Queen's Conservatory with {item:176832|Wildseed Root Grain} in the plots connected to it, and open the cache when it has grown: it may hold either of the two." },
    [1360] = { year = 2020, -- Shimmermist Runner
        text = "It is at the end of the maze of Mistveil Tangle, in {map:1565|Ardenweald}. The way is written on the Tale of the Tangle, a scroll on a tree at 32.5, 53.1: at each crossing, go through the gate whose lamps are blue. From the entrance at 31.0, 54.5 that is left, right, left, right, straight on and left. With a wrong gate, {npc:171767|Shizgher} is not there at the end. Defeat him at 26.4, 59.0 and click the {npc:171699|Shimmermist Runner} he holds. If he is missing, go out to the entrance and start again. {item:174042|Pinch of Faerie Dust}, a common drop of creatures of Ardenweald, lets you fly for 2 minutes over the maze's creatures, through the same gates." },
    [1362] = { year = 2026, -- Spinemaw Gladechewer
        text = "{npc:164107|Gormtamer Tizo} is called by fighting in Mistveil Tangle: kill the {npc:166736|Bristlecone Terror}, the {npc:166735|Deranged Guardian} it rides and the other spriggans there until one of them calls Tizo for help, a yell in the chat. Then {npc:164110|Chompy} comes; kill it, and Tizo appears right there. Whoever takes part in the kill can loot. It may take minutes or an hour; in 09/2026 a player did not make it appear in more than an hour, so it may be broken." },
    [1366] = { year = 2025, -- Bonehoof Tauralus
        text = "Only a Necrolord character with {npc:162151|Neena} at their side gets a chance. To have her: the Abomination Factory at tier 2 and its quest line; then kill {npc:175510|Soul Harvester Anka} near 70, 41 in {map:1536|Maldraxxus}, open the cage with the {item:184354|Soul Harvester Key} and do {quest:59615|Every Dog Has Its Day}. At the factory, build her body with 20 {item:178061|Malleable Flesh} at the {npc:167042|Abominable Stitching Table} and ask her to come with you. Hit Tahonta yourself: one player had no loot when Neena killed it alone. Looting it yourself or through Neena's ability both work. Even so it is rare: players count hundreds of kills." },
    [1370] = { year = 2021, -- Armored Bonehoof Tauralus
        text = "Only a Necrolord character can get it. {npc:168147|Sabriel the Bonecleaver} fights in the middle of the Theater of Pain only while a Necrolord's Anima Conductor is channeling there, and players found in 2021 that the mount only drops for whoever has the conductor at tier 3 and channels it there that day. With a 0.5% chance, buying it is faster." },
    [1379] = { year = 2025, -- Endmire Flyer
        text = "{npc:166521|Famu the Infinite} is hidden until someone talks to {npc:166483|Seeker Hilda}, close by in the Endmire: that starts the event, and after a few waves Famu comes. It is hard alone, but Hilda keeps fighting it if you die. Any covenant can loot." },
    [1387] = { year = 2025, -- Desire's Battle Gargon
        text = "For a Venthyr character, through the {map:1644|Ember Court} of Sinfall, held once a week. The guest is the Countess, who is unlocked with the Ember Court at tier 4 and her invitation quest, {quest:60948|RSVP: The Countess}. Raise her friendship to Best Friend: players report the mount in her tribute at the first Court after that, with her mood at the top at the end. It is not certain: one player in 2025 had 7 Courts as Best Friend without it." },
    [1389] = { year = 2026, -- Battle Gargon Silessa
        text = "For a Venthyr character with the Mirror Network at tier 3. A Broken Mirror is repaired with a {item:181363|Handcrafted Mirror Repair Kit} and leads to a room with a chest, which may have the mount; each chest opens once a day. There are 3 mirrors at a time, always one of 4 fixed groups of 3, out of 12 places. The map marks the mirrors of the group that is on, which the game tells; for a character the mirrors are not for, it marks none. The group changes with the weekly reset, and sometimes in the middle of the week." },
    [1391] = { year = 2021, -- Loyal Gorger
        text = "1. Do {quest:60480|The Endmire}, of {npc:168618|Tessle the Snitch} (65.2, 63.4 in {map:1525|Revendreth}): players who skipped it never saw the item of step 2.\n2. With an {item:173939|Enticing Anima}, a drop of the creatures of the Endmire, light the braziers at 38.8, 72.0 and kill the {npc:160821|Worldedge Gorger} that comes. It may drop the {item:180583|Impressionable Gorger Spawn}; without it, try again the next day.\n3. The spawn runs away. Go down to the Endmire from Darkhaven: it appears and offers a quest. It offers one a day, and the one of day 7 gives the mount." },
    [1392] = { year = 2022, -- Mounts shared by the four covenant features
        own = "Kyrian: buy it from {npc:171973|Binkiros} for 2,500 {currency:1813|Reservoir Anima} after the {achievement:14860|Bare Necessities} achievement, of the Path of Ascension. Night Fae: {item:177700|Divine Untamed Spirit}. Venthyr: Hunt-Captain Korayn's tribute.",
        text = "Each covenant has its own way, through the feature of its sanctum. Necrolord: with the {faction:2462|Stitchmasters} at Exalted, buy it from {npc:159238|Atticus} for 5,000 {currency:1813|Reservoir Anima}. Night Fae: it may come in the {map:1662|Queen's Conservatory} cache when the Divine spirit named below is grown with 4 {item:176832|Wildseed Root Grain}; the Greater spirit of the same kind also gives it, more rarely. Venthyr: it may come in the tribute of the Ember Court guest named below." },
    [1393] = { year = 2021, -- Wild Glimmerfur Prowler
        text = "{npc:168647|Valfir the Unrelenting} is immune until someone uses a Sparkling Animaseed on it. Only a Night Fae character whose Anima Conductor is channeling to Tirna Scithe sees the animaseed, at 30.5, 55.6: pick it up and use the button that appears, on Valfir. Others can join the kill, but only Night Fae get the mount; a low-level Night Fae with no channel of their own got it." },
    [1395] = { year = 2021, -- Phalynx of Humility
        text = "Only for a Kyrian character. With the Anima Conductor, at its first tier, channeling to the Temple of Purity, the chest appears at 60.2, 78.2. Nearby, in a place that changes, there is a bell: click it to start the trial, and cross the floor without being hit by the moving circles; a hit sends you back to the start. At the end, open the chest. If you cannot see the circles, turn on Projected Textures in the graphics options." },
    [1397] = { year = 2025, -- Wildseed Cradle
        text = "Gather {npc:171360|Twinklestar}'s five tools in the Garden of Night, in {map:1565|Ardenweald}: {item:180758|Gardener's Basket} by the water at 40.3, 52.6, {item:180754|Gardener's Hammer} on a cart at 39.8, 54.4, {item:180759|Diary of the Night} on a table up on the tree platform at 39.0, 56.9 (reached by the bridges between the trees), {item:180756|Gardener's Flute} on the ground at 38.5, 58.1 and {item:180757|Gardener's Wand} under a cart at 38.8, 60.1. Use one of them to put the kit together and take it to her at Tirna Vaal, 63.8, 37.6: she gives Moonsight for 10 minutes, which shows the cache behind her. Each player has to gather their own tools." },
    [1404] = { year = 2024, -- Silverwind Larion
        text = "Collect the 50 Anima Crystal Shards of {map:1533|Bastion}, which make the {achievement:14339|Shard Labor} achievement: 45 out in the zone, 2 in The Necrotic Wake and 3 in Spires of Ascension. They are seen only from level 60, and many sit on ledges and columns that take a glider or a careful jump. In the dungeons, take yours before anyone else of the group: players who were beaten to a shard lost it and had to run the dungeon again. With all 50, {npc:171732|Forgelite Hephaesius}, at 59.2, 31.4, forges the {item:180858|Crystal Mallet of Heralds}; ring the Vesper of the Silver Wind with it at 36.0, 25.2 and open the gift that appears beside it." },
    [1408] = { year = 2022, -- Mounts shared by the four covenant features
        own = "Kyrian: buy it from {npc:171973|Binkiros} for 2,500 {currency:1813|Reservoir Anima} after the {achievement:14853|All The Colors of the Painbow} achievement, of the Path of Ascension. Night Fae: {item:178878|Divine Martial Spirit}. Venthyr: Alexandros Mograine's tribute; two players got it the first time they invited him.",
        text = "Each covenant has its own way, through the feature of its sanctum. Necrolord: with the {faction:2462|Stitchmasters} at Exalted, buy it from {npc:159238|Atticus} for 5,000 {currency:1813|Reservoir Anima}. Night Fae: it may come in the {map:1662|Queen's Conservatory} cache when the Divine spirit named below is grown with 4 {item:176832|Wildseed Root Grain}; the Greater spirit of the same kind also gives it, more rarely. Venthyr: it may come in the tribute of the Ember Court guest named below." },
    [1410] = { year = 2026, -- Hulking Deathroc
        text = "{npc:157309|Violet Mistake} is summoned at the {npc:165146|Pool of Mixed Monstrosities}, 58.2, 74.2 in {map:1536|Maldraxxus}. The slimes around drop oozes that anyone can pick up and throw in the pool: Mephitic Goo (blue) from the giants to the south, Viscous Oil (red) from the smaller slimes to the south, Miscible Ooze (yellow) from the giants to the north. At 30 a rare comes out, and which one depends on the mix: for this one, as much blue as red and less yellow, such as 15 blue and 15 red. If no oozes drop, first do {quest:59430|A Plague on Your House} and {quest:58431|Pool of Potions}. During {quest:59234|Mixing A Mess} other players spoil the mix. It can be summoned again and again; its loot comes once a day." },
    [1411] = { year = 2021, -- Predatory Plagueroc
        text = "Only a Necrolord character can get it: others can kill {npc:162741|Gieger} but the mount never drops for them. Only a Necrolord can summon it too: pull the {npc:162815|Final Thread}, at 31.5, 35.2 in {map:1536|Maldraxxus}, next to Gieger's right foot. Once it is up, anyone can join the kill." },
    [1413] = { year = 2022, -- Mounts shared by the four covenant features
        own = "Kyrian: it is the reward for defeating {npc:172333|Azaruux} in a Trial of Wisdom of the Path of Ascension; Binkiros does not sell it. Night Fae: {item:178879|Divine Dutiful Spirit}. Venthyr: Mikanikos' tribute.",
        text = "Each covenant has its own way, through the feature of its sanctum. Necrolord: with the {faction:2462|Stitchmasters} at Exalted, buy it from {npc:159238|Atticus} for 5,000 {currency:1813|Reservoir Anima}. Night Fae: it may come in the {map:1662|Queen's Conservatory} cache when the Divine spirit named below is grown with 4 {item:176832|Wildseed Root Grain}; the Greater spirit of the same kind also gives it, more rarely. Venthyr: it may come in the tribute of the Ember Court guest named below." },
    [1414] = { year = 2024, -- Sinrunner Blanchy
        text = "{npc:173468|Dead Blanchy} appears at 63.1, 43.1 in {map:1525|Revendreth} every 1 to 2 hours and runs faster than a mount: stand in her path and she stops for 5 minutes. Give her one thing a day, in this order, for 6 days, which need not be in a row: 8 {item:182581|Handful of Oats}, from the Sacks of Oats on the farms of north {map:52|Westfall}; the {item:182585|Grooming Brush}, from {npc:173570|Snickersnee} at 63.4, 61.8; 4 {item:182595|Sturdy Horseshoe}, on the roads east and south of Darkhaven; the {item:182599|Bucket of Clean Water}: the empty bucket by the brush, filled in water of Ardenweald or Bastion; the {item:182597|Comfortable Saddle Blanket}, from {npc:171808|Ta'tru} at 51.1, 78.8 for 30 of a meat that changes each week; 3 {item:179271|Dredhollow Apple}, from {npc:167815|Mims} at 40.9, 46.7. Gather everything first." },
    [1415] = { year = 2023, -- Arboreal Gulper
        text = "{npc:164112|Humon'gozz} is summoned. Get an {item:175247|Unusually Large Mushroom}, a rare drop of any creature of {map:1565|Ardenweald}: it lasts 20 minutes in the bags. Take it to the Damp Loam at 32.5, 30.2 and click the loam: a mushroom grows, and he comes out of it. Whoever takes part in the kill can loot, so one mushroom serves a whole group." },
    [1426] = { year = 2026, -- Ascended Skymane
        text = "Ring the five vespers of {achievement:14734|Rallying Cry of the Ascended} within 5 minutes: 33.4, 59.8; 71.9, 38.9; 64.3, 69.8; 39.1, 20.4; 32.2, 17.8. With skyriding one player does it alone. A champion appears at each bell but cannot be attacked there: about a minute after the last bell the five gather at 53.5, 88.4, in the south of {map:1533|Bastion}. Hit them to have a right to the cache, which only a character of level 60 or higher can loot. A bell rung recently stays inactive; a fresh copy of the zone, through War Mode for example, tends to have them ready. Any covenant can do it." },
    [1434] = { year = 2025, -- Deepstar Aurelid
        text = "{npc:180978|Hirukon} only comes for whom fishes with the {item:187923|Aurelid Lure}, and gives the mount to whoever used the lure; the others get a low chance. The lure starts with {item:187662|Strange Goop}, fished in Hirukon's pool at 51.8, 74.3 of {map:1970|Zereth Mortis} (very rare; it is sold at the auction house). Take it to {npc:182194|Baroness Vashj} at 57.6, 92.0 of {map:1536|Maldraxxus}: she asks for {item:187915|Pungent Blobfish}, fished in Coilfang Reservoir at 52.2, 37.9 of {map:102|Zangarmarsh}; {item:187922|Flipper Fish}, fished at 72.8, 24.3 of {map:1355|Nazjatar}, which slips away and is caught by clicking it; and {item:187916|Coilclutch Vine}, on a tower balcony at 34.7, 75.0 of {map:205|Shimmering Expanse}. Use the lure at the pool, fish the Aurelid Cluster and Hirukon comes. Do not kill Hirukon earlier on the same day: the mount does not drop on a second kill." },
    [1437] = { year = 2021, -- Battle-Bound Warhound
        text = "It drops from the elites of the arena of the Theater of Pain, out in the open in {map:1536|Maldraxxus}, not from the dungeon of the same name. They are fights for a group. A character has at most one try a day at each elite; players disagree on whether only the first elite of the day counts, so the safe way is to kill each of them once a day." },
    [1449] = { year = 2022, -- Covenant mounts of the rares of Korthia
        own = "Only for a Necrolord character. {npc:180042|Fleshwing} drops an egg, which hatches after 3 days. The egg comes with no message: look in the bags.",
        text = "Each character has one try a day at each rare of {map:1961|Korthia}. What the rare drops is not the mount, but what leads to it. Players with low renown got them." },
    [1469] = { year = 2023, -- Magmashell
        text = "1. Get an {item:201883|Empty Magma Shell}: a rare drop of the lava snails of the west of {map:2022|The Waking Shores}, {npc:193138|Lavaslurper} among them.\n2. Take it to the {npc:199010|Empowered Snail}, at the bottom of a pool of lava at 71.0, 25.0. When it is not there, it comes back in up to 30 minutes.\n3. Click the snail, not the shell in the bags, and hold for 20 seconds. The lava kills in less than that: take a healer, a way of your class of not dying, or the toy {item:200116|Everlasting Horn of Lavaswimming}." },
    [1475] = { year = 2025, -- Hand of Bahmethra
        text = "Tormentors of Torghast is an event in {map:1543|The Maw} itself, not inside Torghast: every two hours, lieutenants appear at one of the marked spots and, when enough are killed, one of five bosses ({npc:177330|Promathiz} and the others) comes. The mount comes from the {item:185972|Tormentor's Cache} the boss gives once a week per character (1.8% of the caches), or from the boss itself. It is not the Wrath of the Jailer event, which also runs in The Maw. Players count about 50 attempts. The event was broken from 09/2024 to 08/2025 and works again." },
    [1487] = { year = 2022, -- Covenant mounts of the rares of Korthia
        own = "Only for a Night Fae character. {npc:180013|Escaped Wilderling} drops a saddle, an item that starts a quest: the quest gives the mount.",
        text = "Each character has one try a day at each rare of {map:1961|Korthia}. What the rare drops is not the mount, but what leads to it. Players with low renown got them." },
    [1493] = { year = 2022, -- Covenant mounts of the rares of Korthia
        own = "Only for a Kyrian character. {npc:180032|Wild Worldcracker} drops a core, an item that starts a quest: the quest gives the mount.",
        text = "Each character has one try a day at each rare of {map:1961|Korthia}. What the rare drops is not the mount, but what leads to it. Players with low renown got them." },
    [1502] = { year = 2026, -- Fallen Charger
        text = "It appears in {map:1543|The Maw} with a zone message, gallops toward {map:1961|Korthia} and fades away when it gets there: catch it on the way. Whatever its starting point, it crosses one of the two bridges seen from 45.9, 61.9, in the Beastwarrens: wait there and watch the minimap. The wait can be many hours. On a realm with few players the Maw shuts down after being empty for a while and starts again when someone enters, and players report the ride 1 hour after that. Each character can loot it once a day." },
    [1503] = { year = 2024, -- Hand of Nilganihmaht
        text = "The {npc:179572|Hand of Nilganihmaht} is in a cave at 25.5, 36.8 in {map:1543|The Maw}, and only in the rift phase of the zone. With the 5 rings on it, it offers the quest of the mount:\n- {item:186608|Nilganihmaht's Gold Band}: on top of a spire at 19.2, 32.3, a climb.\n- {item:186607|Nilganihmaht's Silver Ring}: in the Domination Sealed Chest at 66.0, 57.4, which takes 4 {item:186727|Seal Breaker Key}.\n- {item:186605|Nilganihmaht's Runed Band}: from {npc:179735|Torglluun}, in the rift.\n- {item:186606|Nilganihmaht's Signet Ring}: from {npc:170303|Exos, Herald of Domination}, who is summoned.\n- {item:186603|Nilganihmaht's Stone Ring}: made of 4 pieces found in Perdition Hold, with {quest:63545|Putting A Plan Together}, of the {quest:63543|Necrolord Assault}, available." },
    [1506] = { year = 2025, -- Crimson Shardhide
        text = "Start at {npc:179729|Caretaker Kah-Kay}, at 60.5, 23.2 in {map:1961|Korthia}, and follow the purple tracks that show on the ground to the remains at 44.4, 29.4: clicking them brings {npc:179684|Malbog}, which a geared character can solo. The event does not need to be up: walking the same path from her makes the remains appear just the same, though now and then it takes a second walk. Each character has one try a day." },
    [1507] = { year = 2021, -- Darkmaul
        text = "{npc:180063|Darkmaul} is friendly and stands at 42.8, 32.7 in {map:1961|Korthia}. Feed it a {item:187153|Tasty Mawshroom} and get on it: the ride counts as soon as you are on, with no need to wait the 2 minutes. After 10 rides the mount is in your bags; with 10 mushrooms saved it is done in one go.\nThe mushroom comes, not every time, from the Invasive Mawshroom, a treasure that appears in many places of Korthia. 5 of them can be opened a day." },
    [1509] = { year = 2025, -- Garnet Razorwing
        text = "{npc:180160|Reliwik the Defiant} is one of the rares of {map:1961|Korthia} that are up only on some days, by a daily rotation. On its days there is a nest at 56.2, 66.1 with three eggs, and clicking the one that can be clicked brings it out. With no nest there, come back the next day; with only two eggs, wait up to 20 minutes for the third. On its day it comes back every 10 to 20 minutes." },
    [1510] = { year = 2021, -- Dusklight Razorwing
        text = "Take 10 {item:187054|Lost Razorwing Egg} to the Razorwing Nest at 25.9, 51.4 in {map:1961|Korthia} and click the nest once for each egg: with the last one the matriarch comes down and gives the mount. The eggs drop from the devourers of Korthia, {npc:177245|Ravenous Gorger} and {npc:177582|Nimble Scavenger} among them, 2 a day at most: it takes 5 days. They can be delivered a few at a time." },
    [1514] = { year = 2025, -- Rampaging Mauler
        text = "{npc:179472|Konthrogz the Obliterator} has no place of its own: when a rare of {map:1961|Korthia} dies, now and then a rift opens where it fell, announced in the zone. Waves of devourers come out and Konthrogz is the last; it has a lot of health and is a fight for a group. There are two kinds of rift: Konthrogz's portal is blue, and a grey one brings another creature. A rift from {npc:180160|Reliwik the Defiant} is always Konthrogz's. Each character has one try a day, and the same rare can be killed again to try for a rift." },
    [1545] = { year = 2023, -- Divine Kiss of Ohn'ahra
        text = "{npc:190022|Godoloto} (56.4, 73.2 in {map:2023|Ohn'ahran Plains}) offers {quest:72512|A Whispering Breeze} to who has renown 25 with the {faction:2503|Maruuk Centaur}, with the last quest of that renown done, has finished the chain of {item:192799|Lizi's Reins}, and carries in the bags, not in the bank:\n- 3 {item:201929|Stolen Breath of Ohn'ahra}: from {npc:186151|Balakar Khan}, the last boss of The Nokhud Offensive, on any difficulty.\n- 1 {item:191507|Exultant Incense} of quality 3: made by alchemists, sold at the auction house.\n- 1 {item:201323|Essence of Awakening}: {npc:196707|Quartermaster Huseng} sells it for 1 {item:194562|Occasional Sand} and 50 {currency:2003|Dragon Isles Supplies}; the sand drops from creatures of {map:2025|Thaldraszus}, {npc:187475|Eternal Sand} among them. Do not use the essence: it is spent.\nThe quest ends with {npc:194796|Ohn'ahra}, at 57.6, 31.9." },
    [1553] = { year = 2026, -- Liberated Slyvern
        text = "{npc:195353|Breezebiter} comes out of the cave at 29.8, 46.3 and flies a wide loop high above the clearing: fly close to it to pull it down. It comes back about 1 to 2 hours after it dies, and there is no lockout: the same character can loot it every time it is killed. Traitor's Rest is often split into shards: if the players around you vanish, you were moved to another one, where the timer is different." },
    [1584] = { year = 2026, -- Colossal Plaguespew Mawrat
        text = "It drops from {npc:182120|Rhuv, Gorger of Ruin}, the dragon of {npc:182114|Iska, Outrider of Ruin}, not from Iska. Iska is one of the three rares of {achievement:15392|Dune Dominance} in {map:1970|Zereth Mortis}: one of them appears now and then with the zone's activity, killing its rares above all, and the wait can be many hours. They can be attacked about 2 minutes after appearing, and today Rhuv dies in a second: hit it the instant it can be hit. In a party, one member's hit counts for all. Loot it at once, before the corpse goes. Rhuv and Iska have separate daily lockouts." },
    [1585] = { year = 2022, -- Colossal Wraithbound Mawrat
        text = "Any Mawsworn Supply Chest of {map:1970|Zereth Mortis} can have it, and there is no daily limit: open every one you find. They stand in the Mawsworn camps. The pyramid at 60.0, 32.0 has three spawns close together, at 59.4, 31.4, 60.1, 32.4 and 61.0, 30.6, and Antecedent Isle, in the north, has four. A chest comes back between 5 minutes and an hour and a half later. After another player opens one it stays for a minute or two, already gone from the minimap: look with your own eyes." },
    [1617] = { year = 2022, -- Verdant Skitterfly
        text = "Reach Renown 25 with {faction:2507|Dragonscale Expedition}. From then on it has a small chance to be inside every Expedition Scout's Pack." },
    [1619] = { year = 2026, -- Ancient Salamanther
        text = "Any of the 16 rares of {map:2151|The Forbidden Reach} can drop it, and a rare you already killed today can still drop it again. Buy the {item:204559|Essence of Divination} for 2,000 {currency:2118|Elemental Overflow} from {npc:200564|Storykeeper Ashekh} in Morqut Village: until the daily reset, spirits warn you about 2 minutes before each rare appears. If it drops, it can be traded to anyone who tagged the same rare." },
    [1656] = { year = 2023, -- Otto
        text = "1. Get one {item:199340|Gold Coin of the Isles}: fished in the Dragon Isles, or 75 {item:199338|Copper Coin of the Isles} traded up with {npc:191608|The Great Swog}.\n2. Buy {item:202102|Immaculate Sac of Swog Treasures} from him with it. Most of the time it has {item:202042|Aquatic Shades}; when it does not, it takes another coin.\n3. Wearing the shades, dance for 5 minutes on the dance floor of the underwater bar in {map:2022|The Waking Shores}, at 19.6, 36.5.\n4. Pick up the {item:202061|Empty Fish Barrel} and fill it: 100 {item:202072|Frigid Floe Fish} (open water around Iskaara), 25 {item:202073|Calamitous Carp} (lava around the Obsidian Citadel) and 1 {item:202074|Kingfin, the Wise Whiskerfish} (water around Algeth'ar Academy).\n5. Take the barrel back to where you danced: Otto offers {quest:72738|The Way to an Otto's Heart}. Accept it at once, or he leaves and the fish are lost." },
    [1671] = { year = 2023, -- Duskwing Ohuna
        text = "{item:207026|Dreamsurge Coalescence} comes from the green orbs scattered over the zone where the Dreamsurge is active, and from the creatures killed there. {npc:210608|Celestine of the Harvest} is at the Dreamsurge symbol on the map." },
    [1672] = { year = 2022, -- Zenet Hatchling
        text = "{npc:193209|Zenet Avis} flies in circles, high over a hill, around 31.4, 63.8 in {map:2023|Ohn'ahran Plains}: fly close to it and it comes down. It drops the {item:200879|Zenet Egg}, which becomes the mount after 7 days in the bags. After a kill it takes hours to come back. Players do not wait: they join groups of the zone in the group finder until they land where it is up." },
    [1732] = { year = 2026, -- Cobalt Shalewing
        text = "{npc:203625|Karokta} lives in a part of {map:2133|Zaralek Cavern} that takes turns with the others: it is up only on some days of a 4-day cycle, and each character loots it once per cycle. It comes back 45 minutes to 2 hours after it dies, and a message in the chat warns just before it appears. The cavern moves you between shards without notice. Since the end of 2025 it scales above your level as a strong elite: bring a group." },
    [1798] = { year = 2025, -- Doomwalker's mounts
        own = "Since 2024 it is no longer a sure drop. During the 2024 event, {npc:158061|Historian Ma'di} also sold it for 5,000 {currency:1166|Timewarped Badges}.",
        text = "Only during WoW's anniversary event, in November. {npc:167749|Doomwalker} is a world boss: since 2024 it stands south of the Caverns of Time, in {map:71|Tanaris}. It needs a group: join the raid that gathers there or one listed in the group finder. Loot is once per day per character, so each alt has its own chance (2024 and 2025)." },
    [1808] = { year = 2025, -- Mounts of the Dreamseed Cache
        own = "Only with a {item:208047|Gigantic Dreamseed} (purple) of yours: the {item:208067|Plump Dreamseed} (blue) and the {item:208066|Small Dreamseed} (green) never give it. About 0.5% per cache, and 2.8% for any of the six of this seed. The game does not say that the bar counts for it. {npc:212797|Talisa Whisperbloom} sells it too, for 1 {item:211376|Seedbloom} of her weekly quest, at renown 18 with the {faction:2574|Dream Wardens}.",
        text = "At a place marked in the {map:2200|Emerald Dream}, click the soil to plant a seed. Minutes later a cache opens for everyone who gave something to that plant.\n{currency:2650|Emerald Dewdrop} is not planted: it is given to a plant already growing, yours or not, and fills its bar. The bar is of everybody who gave, and what counts is reaching 50 and 100: in between, nothing changes.\nThe {item:208047|Gigantic Dreamseed} comes from the zone's rares and from the best bag of {quest:78203|Superbloom}, once an hour." },
    [1810] = { year = 2025, -- Mounts of the Dreamseed Cache
        own = "Only with a {item:208047|Gigantic Dreamseed} (purple) of yours: the {item:208067|Plump Dreamseed} (blue) and the {item:208066|Small Dreamseed} (green) never give it. About 0.5% per cache, and 2.8% for any of the six of this seed. The game does not say that the bar counts for it. {npc:212797|Talisa Whisperbloom} sells it too, for 1 {item:211376|Seedbloom} of her weekly quest, at renown 18 with the {faction:2574|Dream Wardens}.",
        text = "At a place marked in the {map:2200|Emerald Dream}, click the soil to plant a seed. Minutes later a cache opens for everyone who gave something to that plant.\n{currency:2650|Emerald Dewdrop} is not planted: it is given to a plant already growing, yours or not, and fills its bar. The bar is of everybody who gave, and what counts is reaching 50 and 100: in between, nothing changes.\nThe {item:208047|Gigantic Dreamseed} comes from the zone's rares and from the best bag of {quest:78203|Superbloom}, once an hour." },
    [1815] = { year = 2025, -- Mounts of the Dreamseed Cache
        own = "With any seed of yours, or only dewdrops on somebody's plant. About 0.5% per cache. The game says the chance grows when the plant's bar reaches 50 and again at 100, not by how much. It is not sold.",
        text = "At a place marked in the {map:2200|Emerald Dream}, click the soil to plant a seed. Minutes later a cache opens for everyone who gave something to that plant.\n{currency:2650|Emerald Dewdrop} is not planted: it is given to a plant already growing, yours or not, and fills its bar. The bar is of everybody who gave, and what counts is reaching 50 and 100: in between, nothing changes.\nThe {item:208047|Gigantic Dreamseed} comes from the zone's rares and from the best bag of {quest:78203|Superbloom}, once an hour." },
    [1816] = { year = 2025, -- Mounts of the Dreamseed Cache
        own = "Only with a {item:208047|Gigantic Dreamseed} (purple) of yours: the {item:208067|Plump Dreamseed} (blue) and the {item:208066|Small Dreamseed} (green) never give it. About 0.5% per cache, and 2.8% for any of the six of this seed. The game does not say that the bar counts for it. {npc:212797|Talisa Whisperbloom} sells it too, for 1 {item:211376|Seedbloom} of her weekly quest, at renown 18 with the {faction:2574|Dream Wardens}.",
        text = "At a place marked in the {map:2200|Emerald Dream}, click the soil to plant a seed. Minutes later a cache opens for everyone who gave something to that plant.\n{currency:2650|Emerald Dewdrop} is not planted: it is given to a plant already growing, yours or not, and fills its bar. The bar is of everybody who gave, and what counts is reaching 50 and 100: in between, nothing changes.\nThe {item:208047|Gigantic Dreamseed} comes from the zone's rares and from the best bag of {quest:78203|Superbloom}, once an hour." },
    [1817] = { year = 2025, -- Mounts of the Dreamseed Cache
        own = "Only with a {item:208047|Gigantic Dreamseed} (purple) of yours: the {item:208067|Plump Dreamseed} (blue) and the {item:208066|Small Dreamseed} (green) never give it. About 0.5% per cache, and 2.8% for any of the six of this seed. The game does not say that the bar counts for it. {npc:212797|Talisa Whisperbloom} sells it too, for 1 {item:211376|Seedbloom} of her weekly quest, at renown 18 with the {faction:2574|Dream Wardens}.",
        text = "At a place marked in the {map:2200|Emerald Dream}, click the soil to plant a seed. Minutes later a cache opens for everyone who gave something to that plant.\n{currency:2650|Emerald Dewdrop} is not planted: it is given to a plant already growing, yours or not, and fills its bar. The bar is of everybody who gave, and what counts is reaching 50 and 100: in between, nothing changes.\nThe {item:208047|Gigantic Dreamseed} comes from the zone's rares and from the best bag of {quest:78203|Superbloom}, once an hour." },
    [1833] = { year = 2025, -- Mounts of the Dreamseed Cache
        own = "Only with a {item:208047|Gigantic Dreamseed} (purple) of yours: the {item:208067|Plump Dreamseed} (blue) and the {item:208066|Small Dreamseed} (green) never give it. About 0.5% per cache, and 2.8% for any of the six of this seed. The game does not say that the bar counts for it. {npc:212797|Talisa Whisperbloom} sells it too, for 1 {item:211376|Seedbloom} of her weekly quest, at renown 18 with the {faction:2574|Dream Wardens}.",
        text = "At a place marked in the {map:2200|Emerald Dream}, click the soil to plant a seed. Minutes later a cache opens for everyone who gave something to that plant.\n{currency:2650|Emerald Dewdrop} is not planted: it is given to a plant already growing, yours or not, and fills its bar. The bar is of everybody who gave, and what counts is reaching 50 and 100: in between, nothing changes.\nThe {item:208047|Gigantic Dreamseed} comes from the zone's rares and from the best bag of {quest:78203|Superbloom}, once an hour." },
    [1834] = { year = 2024, -- Ochre Dreamtalon
        text = "The quest that gives it is the last of 5, and the chain takes 23 days: a plant grows between the quests. The waits are 5 days, 5 days, 3 days for the fertilizer of the third quest, 5 days and 5 days, each counted from when the quest before is handed in.\n1. Click the burning sprout at 48.7, 67.9 in {map:2200|Emerald Dream}, ON FOOT: mounted, it does not answer. Click it twice, to put the fire out and to clean it, and it gives {quest:77677|Some Water...}.\n2. The next quests come from {npc:208337|Professor Ash}, the herbalism trainer at 49.6, 62.8, or from the plant itself.\n3. In {quest:77697|The Right Food...}, combine the three things by clicking the {item:208644|Lasher Plant Matter}: the bananas, clicked, are eaten. When the fertilizer is ready, leave the game and come back before using it.\nA player reports that the sprout only answered after chapter 5 of the zone's story." },
    [1835] = { year = 2025, -- Mounts of the Dreamseed Cache
        own = "Only with a {item:208047|Gigantic Dreamseed} (purple) of yours: the {item:208067|Plump Dreamseed} (blue) and the {item:208066|Small Dreamseed} (green) never give it. About 0.5% per cache, and 2.8% for any of the six of this seed. The game does not say that the bar counts for it. {npc:212797|Talisa Whisperbloom} sells it too, for 1 {item:211376|Seedbloom} of her weekly quest, at renown 18 with the {faction:2574|Dream Wardens}.",
        text = "At a place marked in the {map:2200|Emerald Dream}, click the soil to plant a seed. Minutes later a cache opens for everyone who gave something to that plant.\n{currency:2650|Emerald Dewdrop} is not planted: it is given to a plant already growing, yours or not, and fills its bar. The bar is of everybody who gave, and what counts is reaching 50 and 100: in between, nothing changes.\nThe {item:208047|Gigantic Dreamseed} comes from the zone's rares and from the best bag of {quest:78203|Superbloom}, once an hour." },
    [1943] = { year = 2026, -- Incognitro, the Indecipherable Felcycle
        text = "A long secret chain, still open after the 2024 anniversary. 1. Earn {achievement:40870|Azeroth's Greatest Detective}: outside the event, turn in the 11 Celebration Crates to {npc:234262|Alyx} in {map:2339|Dornogal}. 2. The {npc:230042|Dalaran Survivor} in Dornogal (55.0, 29.0) leads you to a cave in Azj-Kahet and the {item:228938|Peculiar Gem}. The toy {item:208092|Torch of Pyrreth}, used on the stump of Marshal's Refuge (44.5, 8.0, {map:78|Un'Goro Crater}), gives the {item:228941|Inert Peculiar Key}: combine them. 3. With the key, use the torch at the east side of Karazhan (47.0, 69.0, {map:42|Deadwind Pass}): inside the portal, light eight pillars, each a riddle. 4. Back in that cave, the {item:228966|Starry-Eyed Goggles} show a platform: enter 84847078 on its console to open this chest." },
    [1948] = { year = 2026, -- Voidfire Deathcycle
        text = "It is rebuilt, not looted. In {map:2404|Vision of Stormwind}, with at least 1 mask on, a rider on the cycle is in the Dwarven District, at 62.1, 31.2. Bring the cycle low until the rider jumps off, kill him, then talk to the cycle. Do it slowly: players who killed it too fast never got to talk to it.\nFrom then on the cycle is parked in Dornogal, beside the way in to the visions. It asks for six kinds of part: {item:240188|Void-Forged Inline Four Engine}, {item:240190|Deathcycle Exhaust System}, {item:240182|Skull-Scythe Handlebars}, {item:240185|Pulsing Void Crystal}, {item:240181|Boarhide Deathcycle Seat} and 2 {item:240179|Voidflame Wheel}. Each is put together from a piece found in the visions, some in Stormwind and some in Orgrimmar, and from materials that are bought or crafted. Install them all and press the button." },
    [1959] = { year = 2024, -- Compass Rose
        text = "Only in Hearthstone's 10th anniversary event in WoW, from March 11 to 22, 2024. A portal opened every hour (every 30 minutes from March 15) in Stormwind Harbor, in Durotar outside Orgrimmar and in {map:2112|Valdrakken}. After 5 minutes, Hearthstone minions came out, and {npc:215146|Dr. Boom}, who drops it, came after {npc:215147|Patches} or the {npc:215141|Chillwind Yeti} died. The same character could loot him several times a day." },
    [2038] = { year = 2026, -- Clayscale Hornstrider
        text = "It comes from {quest:79226|The Big Dig: Traitor's Rest}, an event of the Azerothian Archives in {map:2024|The Azure Span} that starts every hour, at minute 30. After about 9 minutes of digging, {npc:208029|Doomshadow} lands: hit it to get loot, because the crowd kills it fast. It drops from it and from the tomes the event gives, with no lockout: the same character can try every hour." },
    [2119] = { year = 2026, -- Stonevault Mechsuit
        text = "{npc:219440|High Speaker Eirich}, in The Stonevault on Mythic, can drop {item:226683|Malfunctioning Mechsuit}, which starts a chain with {npc:213875|Speaker Jurlax} (47.0, 32.4 in {map:2214|The Ringing Deeps}). He asks for three trinkets, one at a time: {item:219301|Overclocked Gear-a-Rang Launcher} from {npc:213216|Speaker Dorlita} in The Stonevault, {item:219299|Synergistic Brewterializer} from {npc:218523|Goldie Baronbottom} in Cinderbrew Meadery and {item:219306|Burin of the Candle King} from {npc:208745|The Candle King} in Darkflame Cleft. The chain is of the whole account, and a trinket only drops for a class that uses it (Goldie's is of Intellect): another character may loot it. Any item level serves." },
    [2144] = { year = 2026, -- Delver's mounts sold by Reno Jackson (Dirigible, Gob-Trotter, Mana-Skimmer, OC91 Chariot)
        text = "Whatever the journal says, since Midnight {npc:226250|Reno Jackson}, in Dornogal, sells it for 10,000 {currency:2815|Resonance Crystals}." },
    [2159] = { year = 2026, -- Machine Defense Unit 1-11
        text = "The event of the {npc:227273|Awakened Machinist} in {map:2214|The Ringing Deeps} has 20 waves, and the mount only comes in the Awakened Cache that appears after the last one. About 6 caches in 100 have it; reports go from 10 to more than 70 runs. The cache comes once a week per character. The creatures are level 80 for everyone: a lower character does not get an easier fight." },
    [2161] = { year = 2026, -- Vivid Chloroceros, Elder Glowmite (Luminous Dust)
        text = "{currency:3385|Luminous Dust} comes from the Glowing Moths scattered over {map:2413|Harandar}, 120 in all. They open in three groups of 40, at Renown 1, 5 and 6 with {faction:2704|Hara'ti}; the map only marks each group later, at Renown 2, 6 and 11. The player who mapped them advises reaching Renown 9 before hunting." },
    [2165] = { year = 2026, -- Soaring Meaderbee
        text = "{npc:226205|Cendvin} (74.4, 45.2 in {map:2248|Isle of Dorn}) asks for 900 {item:225557|Sizzling Cinderpollen}. It drops from the elite creatures west of the Cinderbrew Meadery: the bees and, on the shore around 73, 33, {npc:222797|Tempest Wolf} and {npc:222796|Rustcloud Runt}. The pollen passes between the characters of the account. Players count 3 to 4 hours." },
    [2176] = { year = 2026, -- Alunira
        text = "Alunira flies around the highest peak of {map:2248|Isle of Dorn} (23.2, 58.5) behind a shield. Any creature of the island has a small chance to drop {item:224025|Crackling Shard}; 10 of them make a {item:224026|Storm Vessel}, which breaks the shield. The small named rares that come back in minutes drop shards far more often than common creatures, and shards pass between the characters of the account.\nShe gives loot once a day. Do not kill her in somebody else's group on the day you mean to use your own vessel: players lost the vessel that way." },
    [2178] = { year = 2026, -- Nesting Swarmite
        text = "In the Horrific Visions, each district has a pile of trash; clicking it calls creatures and, now and then, the Nesting Swarmite, which always drops the mount. No mask is needed. Players check one or two piles, leave the vision and enter again; reports go from the first pile to more than 70 attempts.\n{map:2404|Vision of Stormwind}: 55.8, 49.3 · 62.9, 30.7 · 73.6, 62.7 · 66.1, 76.3 · 52.6, 77.3.\n{map:2403|Vision of Orgrimmar}: 47.8, 75.0 · 40.7, 79.3 · 50.9, 45.2 · 69.0, 49.8 · 57.5, 60.6, this one inside a shop and smaller." },
    [2192] = { year = 2026, -- Beledar's Spawn
        text = "{npc:207802|Beledar's Spawn} appears in {map:2215|Hallowfall} when Beledar goes dark, every 3 hours, the first time 1 hour after the daily reset, in one of several spots, and leaves when the dark ends, 30 minutes later. A character of level 70 can loot it. It gives loot once a day per character, and about 5.5% of the kills give the mount. It dies in seconds: players join a group that has every spot covered." },
    [2194] = { year = 2026, -- Dauntless Imperial Lynx
        text = "It comes in {item:228741|Lamplighter Supply Satchel}, given by the fires of {quest:76586|Spreading the Light} in {map:2215|Hallowfall}: the main ones, and the side quests the small fires give for 3 crystals. About 0.6% of the satchels have it, and reports go past 300. A character of level 70 can do it." },
    [2205] = { year = 2025, -- Ol' Mole Rufus
        text = "Five levers spread over {map:2214|The Ringing Deeps} have to be pulled at the same time, so it takes five players. A message in the chat says it worked, and some time later {npc:220285|Lurker of the Deeps} appears. Loot once a day per character, also below level 80. Wowhead counts the mount in about 6% of the kills; players who counted in raids say fewer." },
    [2222] = { year = 2026, -- Siesbarg
        text = "{npc:216046|Tka'ktath} (63, 66 in {map:2255|Azj-Kahet}, on top of a platform) drops {item:225952|Vial of Tka'ktath's Blood} to characters of level 78 or more. He takes hours to come back and is hard alone; the loot is once a day. The vial starts a chain that asks, in this order, for 1,500 {item:225950|Nerubian Chitin}, 1,000 {item:226135|Nerubian Venom} and 500 {item:226136|Nerubian Blood}, all from nerubian creatures, the blood from few of them. The chain is of the character. Players farm the first rooms of the dungeons Ara-Kara and City of Threads with followers, leaving and entering again. The old nerubian dungeons, like Azjol-Nerub, do not count. For the blood, one player got 270 in 40 minutes from the elites around 65.0, 12.7." },
    [2225] = { year = 2025, -- Timewalking vendor mounts
        text = "The vendor is only there while the Timewalking of their expansion is on. {currency:1166|Timewarped Badge} can be moved between the characters of the account, in the currency tab." },
    [2274] = { year = 2025, -- Undermine cartel troves (Blackwater, Steamwheedle, Venture Co., Bilgewater)
        own = "About 28% of the troves of its cartel have it.",
        text = "The trove is what the cartel gives each time the reputation bar fills again after Exalted. Many players got the mount in the first trove, one needed 16." },
    [2276] = { year = 2025, -- Ando the Gat's mounts (Darkfuse Chompactor, Flarendo the Furious, Thunderdrum Misfire)
        text = "{npc:235621|Ando the Gat} is INSIDE the raid Liberation of Undermine, up the stairs from the entrance. Players get to him through the Raid Finder, which {npc:231045|Paks Topskimmer} opens at 43.4, 51.5 in {map:2346|Undermine}." },
    [2278] = { year = 2025, -- Ando the Gat's mounts (Darkfuse Chompactor, Flarendo the Furious, Thunderdrum Misfire)
        text = "{npc:235621|Ando the Gat} is INSIDE the raid Liberation of Undermine, up the stairs from the entrance. Players get to him through the Raid Finder, which {npc:231045|Paks Topskimmer} opens at 43.4, 51.5 in {map:2346|Undermine}." },
    [2279] = { year = 2025, -- Ando the Gat's mounts (Darkfuse Chompactor, Flarendo the Furious, Thunderdrum Misfire)
        text = "{npc:235621|Ando the Gat} is INSIDE the raid Liberation of Undermine, up the stairs from the entrance. Players get to him through the Raid Finder, which {npc:231045|Paks Topskimmer} opens at 43.4, 51.5 in {map:2346|Undermine}." },
    [2281] = { year = 2025, -- Undermine cartel troves (Blackwater, Steamwheedle, Venture Co., Bilgewater)
        own = "About 25% of the troves of its cartel have it.",
        text = "The trove is what the cartel gives each time the reputation bar fills again after Exalted. Many players got the mount in the first trove, one needed 16." },
    [2283] = { year = 2026, -- Miscellaneous Mechanica mounts (Innovation Investigator, Asset Advocator, Margin Manipulator)
        text = "{item:234741|Miscellaneous Mechanica} drops, seldom, from the rares each cartel calls in {map:2346|Undermine}, and not only on the first kill of the day; players also found it in the overflowing dumpsters. {npc:228286|Skedgit Cinderbangs} is at 43.3, 82.8. Players call it one of the longest farms of the expansion: one of them bought the third mount at the auction house. A player found 1 or 2 in each {item:232465|Darkfuse Trove} and counts about 30 hours for the 25 of one mount." },
    [2289] = { year = 2025, -- Undermine cartel troves (Blackwater, Steamwheedle, Venture Co., Bilgewater)
        own = "About 28% of the troves of its cartel have it.",
        text = "The trove is what the cartel gives each time the reputation bar fills again after Exalted. Many players got the mount in the first trove, one needed 16." },
    [2290] = { year = 2026, -- Miscellaneous Mechanica mounts (Innovation Investigator, Asset Advocator, Margin Manipulator)
        text = "{item:234741|Miscellaneous Mechanica} drops, seldom, from the rares each cartel calls in {map:2346|Undermine}, and not only on the first kill of the day; players also found it in the overflowing dumpsters. {npc:228286|Skedgit Cinderbangs} is at 43.3, 82.8. Players call it one of the longest farms of the expansion: one of them bought the third mount at the auction house. A player found 1 or 2 in each {item:232465|Darkfuse Trove} and counts about 30 hours for the 25 of one mount." },
    [2291] = { year = 2026, -- Salvaged Goblin Gazillionaire's Flying Machine
        text = "{npc:234621|Gallagio Garbage} may appear when the bar of trash shoveled of a S.C.R.A.P. event reaches 500, and not when the event ends. It takes 3 players or more to fill the bar. The same character can kill it again and again on the same day; about 1.6% of the kills give the mount." },
    [2292] = { year = 2026, -- Miscellaneous Mechanica mounts (Innovation Investigator, Asset Advocator, Margin Manipulator)
        text = "{item:234741|Miscellaneous Mechanica} drops, seldom, from the rares each cartel calls in {map:2346|Undermine}, and not only on the first kill of the day; players also found it in the overflowing dumpsters. {npc:228286|Skedgit Cinderbangs} is at 43.3, 82.8. Players call it one of the longest farms of the expansion: one of them bought the third mount at the auction house. A player found 1 or 2 in each {item:232465|Darkfuse Trove} and counts about 30 hours for the 25 of one mount." },
    [2293] = { year = 2025, -- Darkfuse Spy-Eye
        text = "{npc:231310|Darkfuse Precipitant} is called with {item:229823|Canister of Darkfuse Solution}, which {npc:231396|Sitch Lowdown} sells to who has Renown 6 with {faction:2653|The Cartels of Undermine} and is Friendly with {faction:2669|Darkfuse Solutions}; it goes in the pylon at 40.6, 91.8 of {map:2346|Undermine}. Whoever is there can loot, once a week per character. About 4.3% of the kills give the mount." },
    [2295] = { year = 2025, -- Undermine cartel troves (Blackwater, Steamwheedle, Venture Co., Bilgewater)
        own = "About 25% of the troves of its cartel have it.",
        text = "The trove is what the cartel gives each time the reputation bar fills again after Exalted. Many players got the mount in the first trove, one needed 16." },
    [2296] = { year = 2026, -- Delver's mounts sold by Reno Jackson (Dirigible, Gob-Trotter, Mana-Skimmer, OC91 Chariot)
        text = "Whatever the journal says, since Midnight {npc:226250|Reno Jackson}, in Dornogal, sells it for 10,000 {currency:2815|Resonance Crystals}." },
    [2303] = { year = 2026, -- Violet Goblin Shredder
        text = "It comes with the reward of a streak of jobs of Shipping & Handling in {map:2346|Undermine}, to who has Renown 8 with {faction:2653|The Cartels of Undermine}. Players got it outside the surge too, and not on the first streak of the day." },
    [2317] = { year = 2025, -- Timewalking vendor mounts
        text = "The vendor is only there while the Timewalking of their expansion is on. {currency:1166|Timewarped Badge} can be moved between the characters of the account, in the currency tab." },
    [2322] = { year = 2026, -- Thrayir, Eyes of the Siren
        text = "Thrayir lies in The Forgotten Vault of {map:2369|Siren Isle} (cave at 44.0, 23.1) among 5 runestones, each asking for a runekey. Keys are only found and used in the storm: {npc:227815|Suzie Boltwrench} (69.0, 49.1) takes you into it once the week's {quest:84850|Serpent's Wrath} is done.\n- {item:232571|Whirling Runekey}: {npc:231368|Ksvir the Forgotten}, in the vault.\n- {item:232569|Cyclonic Runekey}: {npc:231357|Zek'ul the Shipbreaker}, or fished where he appears.\n- {item:232572|Torrential Runekey}: 7 {item:234328|Torrential Fragment}, from any creature in the storm.\n- {item:232573|Thunderous Runekey}: 5 {item:232605|Thunderous Fragment}, from chests.\n- {item:232570|Turbulent Runekey}: 3 {item:234327|Turbulent Fragment}, at 38.2, 51.8 · 67.1, 78.4 · 52.4, 38.6.\nUse each key when you get it: the progress is kept." },
    [2334] = { year = 2026, -- Bronze Goblin Waveshredder
        text = "{item:232465|Darkfuse Trove} is what {faction:2669|Darkfuse Solutions} gives each time the reputation bar fills again after Exalted. About 19% of the troves have the mount." },
    [2470] = { year = 2025, -- Timewalking vendor mounts
        text = "The vendor is only there while the Timewalking of their expansion is on. {currency:1166|Timewarped Badge} can be moved between the characters of the account, in the currency tab." },
    [2471] = { year = 2025, -- Timewalking vendor mounts
        text = "The vendor is only there while the Timewalking of their expansion is on. {currency:1166|Timewarped Badge} can be moved between the characters of the account, in the currency tab." },
    [2473] = { year = 2025, -- Timewalking vendor mounts
        text = "The vendor is only there while the Timewalking of their expansion is on. {currency:1166|Timewarped Badge} can be moved between the characters of the account, in the currency tab." },
    [2474] = { year = 2025, -- Timewalking vendor mounts
        text = "The vendor is only there while the Timewalking of their expansion is on. {currency:1166|Timewarped Badge} can be moved between the characters of the account, in the currency tab." },
    [2496] = { year = 2026, -- Void-Scarred Gryphon
        text = "In {map:2404|Vision of Stormwind}, one of the Horrific Visions, with at least 2 masks on. Two torn notes in the Trade District say what the gryphon eats: the one at 65.6, 71.6 says raw or cooked, the one at 68.7, 73.3 says which food. Put it in the bowl at 67.8, 73.3 and rattle the bowl: the gryphon that lands drops the mount. The wrong food brings rats and costs the run, so players carry the 8. Raw: {item:222741|Fresh Fillet}, {item:222737|Chopped Mycobloom}, {item:222739|Spiced Meat Stock}, {item:222738|Portioned Steak}. Cooked: {item:222702|Skewered Fillet}, {item:222705|Roasted Mycobloom}, {item:222703|Simple Stew}, {item:222704|Unseasoned Field Steak}. The district does not have to be finished. Only one player of a group gets the mount from each kill." },
    [2497] = { year = 2025, -- Void-Forged Stallion
        text = "In {map:2404|Vision of Stormwind}, one of the Horrific Visions, with at least 1 mask on, pick up the 4 horseshoes, one per district: 56.1, 55.5 · 75.6, 56.8 · 61.5, 75.6 · 51.0, 84.1. Take them to the forge at 62.9, 37.1, in the Dwarven District: the stallion that appears drops the mount. Loot it, for it does not come by mail. It only works in a week whose vision is Stormwind. Only one player of a group gets the mount from each kill." },
    [2498] = { year = 2025, -- Void-Scarred Pack Mother
        text = "In {map:2403|Vision of Orgrimmar}, one of the Horrific Visions, with at least 1 mask on: pick up the wolf saddle at 67.4, 36.2 and the bag of wolf tack at 39.2, 49.6, then click the wolf skin rug at 60.9, 55.1, inside the leatherworking shop. The wolf that appears drops the mount. Only one player of a group gets the mount from each kill." },
    [2499] = { year = 2026, -- Void-Scarred Windrider
        text = "In {map:2403|Vision of Orgrimmar}, one of the Horrific Visions, with at least 2 masks on: finish the Valley of Wisdom, which opens the elevator at 49.2, 50.7. Go up and south, to where the wind riders stand (48.7, 54.9), and kill the waves until the matriarch comes: she drops the mount. Only one player of a group gets the mount from each kill." },
    [2502] = { year = 2025, -- Void-Crystal Panther
        text = "What it is made of only comes from the Horrific Visions, with at least 1 mask on, and no profession is needed to gather it. Kill {npc:241024|Big Keech} once, in the Valley of Honor of the vision of Orgrimmar: he gives {item:238924|Void-Bound Orb of Mystery} and, to a jewelcrafter, the recipe. From then on the altar of the Valley of Wisdom gives {item:239107|Black Blood Infused Bar} and each reward chest of a run gives one {item:239106|Shadow-Infused Onyx}. Players count 5 runs. Who is not a jewelcrafter has it made through a crafting order." },
    [2505] = { year = 2025, -- Resplendent K'arroc
        text = "It is not a world quest, whatever the journal says: {npc:231820|Ve'nari}, in the Oasis of {map:2371|K'aresh}, offers {quest:88976|The Hope of K'aresh} to who has {achievement:41811|Ecological Stability}." },
    [2511] = { year = 2025, -- Terror of the Night
        text = "The warrants are weekly: one of 6 comes each week, at random, at 48.7, 57.7 in {map:2472|Tazavesh, the Veiled Market}, and each is a short chain that ends with a rare to call and kill. With the 6 done comes the mount: six weeks at least." },
    [2512] = { year = 2026, -- Delver's mounts sold by Reno Jackson (Dirigible, Gob-Trotter, Mana-Skimmer, OC91 Chariot)
        text = "Whatever the journal says, since Midnight {npc:226250|Reno Jackson}, in Dornogal, sells it for 10,000 {currency:2815|Resonance Crystals}." },
    [2535] = { year = 2026, -- Void-Scarred Lynx
        text = "It comes in {item:239546|Confiscated Cultist's Bag}, the bag of the DAILY quests of the incursions in {map:2215|Hallowfall}, and not in the weekly satchel. About 0.7% of the bags have it; reports go from the 3rd bag to more than 500." },
    [2552] = { year = 2025, -- Lavender K'arroc, Acidic Void Creeper (Untethered Coin)
        text = "{quest:91093|More Than Just a Phase} gives 7 {currency:3303|Untethered Coin} per week to the whole account. {npc:241624|Shad'anis} asks for 66 for everything she sells." },
    [2557] = { year = 2025, -- Lavender K'arroc, Acidic Void Creeper (Untethered Coin)
        text = "{quest:91093|More Than Just a Phase} gives 7 {currency:3303|Untethered Coin} per week to the whole account. {npc:241624|Shad'anis} asks for 66 for everything she sells." },
    [2560] = { year = 2025, -- Blue Barry
        text = "At Renown 9 with {faction:2658|The K'aresh Trust}, {npc:238016|Ba'eth} (57.6, 58.1 in {map:2472|Tazavesh, the Veiled Market}) starts a chain that moves one step per day, from {quest:90663|Stealing What is Ours} to {quest:90769|A Blue for You}, which gives the mount. Four days at least, and a day skipped is a day later." },
    [2561] = { year = 2025, -- Curious Slateback
        text = "{item:245611|Wriggling Pinnacle Cache} comes once a week, and about 3 caches in 100 have the mount. Players opened it every week for months." },
    [2586] = { year = 2025, -- Timewalking vendor mounts
        text = "The vendor is only there while the Timewalking of their expansion is on. {currency:1166|Timewarped Badge} can be moved between the characters of the account, in the currency tab." },
    [2587] = { year = 2025, -- Timewalking vendor mounts
        text = "The vendor is only there while the Timewalking of their expansion is on. {currency:1166|Timewarped Badge} can be moved between the characters of the account, in the currency tab." },
    [2601] = { year = 2025, -- Pearlescent Krolusk
        text = "You must be in Phase Diving to see and attack {npc:232195|Urmag}. It comes back every 10 to 20 minutes, and loot is once a day per character, so alts help. When it cannot be attacked, it is under the veil of the world boss nearby: pull it away from the boss, or behind the piece of dome next to its spawn, until that effect drops." },
    [2602] = { year = 2025, -- Translocated Gorger
        text = "It is made from 20 {item:246240|Devoured Energy-Pod}. Each of the 4 rares of the devourer attacks gives one per week to the account: {npc:231229|Korgoth the Hungerer} (71.8, 28.2), {npc:234970|Miasmawrath} (50.6, 54.0) and a third at 49.5, 64.2 in {map:2371|K'aresh}, {npc:235104|The Wallbreaker} (28.6, 74.3) in {map:2472|Tazavesh, the Veiled Market}. That is 4 per week at most, so 5 weeks. One attack is on at a time, and the map shows it; the rare comes when the bar of devourers killed is full." },
    [2603] = { year = 2026, -- Sthaarbs's Last Lunch
        text = "{npc:234845|Sthaarbs} appears in the middle of the Oasis of {map:2371|K'aresh} (74.0, 32.5) about an hour after it last died, and can only be fought from inside Phase Diving: it takes {item:235499|Reshii Wraps} and level 80. Beside the phase conduit at 75.8, 33.0 an extra button takes you to the platforms around it. Loot once a week per character; about 6.8% of the kills give the mount." },
    [2604] = { year = 2026, -- Delver's mounts sold by Reno Jackson (Dirigible, Gob-Trotter, Mana-Skimmer, OC91 Chariot)
        text = "Whatever the journal says, since Midnight {npc:226250|Reno Jackson}, in Dornogal, sells it for 10,000 {currency:2815|Resonance Crystals}." },
    [2605] = { year = 2025, -- Inarius' Charger
        text = "Only during the Greedy Emissary event (July 2025). {npc:205490|Treasure Goblins} came out of portals in Stormwind, Orgrimmar and Dornogal, and in {map:2346|Undermine} after rares were killed, where raid groups farmed them. There is no lockout: the same character can loot one goblin after another. If it drops in a group, it can be traded to the players of that group." },
    [2615] = { year = 2026, -- Rootstalker Grimlynx, Vibrant Petalwing (Harandar rares)
        text = "Any rare of {map:2413|Harandar} can drop it, each with a chance of about 0.1%. A rare gives loot once a day per character, so players repeat the round on other characters, level 80 ones included. Reports go from the first kill to more than 2,000." },
    [2655] = { year = 2026, -- Phase-Lost Slateback
        text = "The orbs of {achievement:61017|Phase-Lost-and-Found} only show inside Phase Diving, in {map:2371|K'aresh} and in Tazavesh, and ask for {item:235499|Reshii Wraps} at rank 3. About 20% of the orbs give a weapon, always one you do not have yet. Two players cannot take the same orb. Players did it in 30 minutes to a few hours, going round the isles." },
    [2693] = { year = 2026, -- Blessed Amani Burrower, Amani Sunfeather (Abundance vendor)
        text = "The journal says 1,600 {currency:3377|Unalloyed Abundance}, but {npc:241928|Chel the Chip} charges 6,400." },
    [2708] = { year = 2026, -- Rootstalker Grimlynx, Vibrant Petalwing (Harandar rares)
        text = "Any rare of {map:2413|Harandar} can drop it, each with a chance of about 0.1%. A rare gives loot once a day per character, so players repeat the round on other characters, level 80 ones included. Reports go from the first kill to more than 2,000." },
    [2713] = { year = 2026, -- Ruddy Sporeglider
        text = "The Peculiar Cauldron (40.7, 28.1 in {map:2413|Harandar}) opens with 150 {item:260531|Crystalized Resin Fragment}. They come, 2 to 7 at a time, from the Flame-Hardened Sap of Teldrassil lying in the river that runs from 40.0, 21.4 to 49.3, 51.2, and in no other water. The sap comes back as fast as it is picked. From high above the river its outline is easier to see." },
    [2747] = { year = 2026, -- Untainted Grove Crawler
        text = "In {map:2413|Harandar}: touch the Fungal Mallet at 41.3, 67.9, which gives a buff of 5 minutes, and with the buff ring the Mycelium Gong at 46.6, 67.8. The Sporespawned Cache appears beside the gong. One player only saw the gong after killing the creatures around it; another clicked the cache, got nothing, and received the mount by mail hours later." },
    [2749] = { year = 2026, -- Echo of Aln'sharan
        text = "1. Do the short chain of {npc:245637|Su'meera} that starts with {quest:91063|The Blooming Lattice} (65.4, 22.6 in {map:2413|Harandar}), then the chain of {npc:242358|Kuri} (67.8, 24.8), from {quest:90467|Tales of the Sky} to {quest:90474|The Legend of Aln'sharan}. One character of the account is enough.\n2. From then on the creatures of Harandar drop {item:255826|Mysterious Skyshards}, in delves and dungeons too; rares drop them far more often. Gather 500.\n3. Give them to Kuri at 66.2, 25.5 with the extra action button. Nothing seems to happen, but you get a buff.\n4. Aln'sharan flies high over the zone and hurts whoever gets near. Dismount in the air next to his head and click him, with a slow fall at hand.\nPlayers lost the buff, and the 500 shards with it, by joining a group or a battleground before step 4." },
    [2751] = { year = 2026, -- Augmented Stormray, Sanguine Harrower (Voidstorm rares)
        text = "Any rare of {map:2405|Voidstorm} can drop it, each with a chance of about 0.1%. A rare gives loot once a day per character, so players repeat the round on other characters, level 80 ones included. Reports go from the first kill to more than 2,000." },
    [2758] = { year = 2026, -- Cobalt Dragonhawk, Cerulean Hawkstrider (Eversong Woods rares)
        text = "Any rare of {map:2395|Eversong Woods} can drop it, each with a chance of about 0.1%. A rare gives loot once a day per character, so players repeat the round on other characters. Reports go from the first kill to more than 2,000." },
    [2760] = { year = 2026, -- Amani Sharptalon, Witherbark Pango (Zul'Aman rares)
        text = "Any rare of {map:2437|Zul'Aman} can drop it, each with a chance of about 0.1%. A rare gives loot once a day per character, so players repeat the round on other characters. Reports go from a few kills to more than 2,000." },
    [2762] = { year = 2026, -- Cobalt Dragonhawk, Cerulean Hawkstrider (Eversong Woods rares)
        text = "Any rare of {map:2395|Eversong Woods} can drop it, each with a chance of about 0.1%. A rare gives loot once a day per character, so players repeat the round on other characters. Reports go from the first kill to more than 2,000." },
    [2764] = { year = 2026, -- Duskbrute Harrower
        text = "{item:267299|Slayer's Duellum Trove} is what {faction:2770|Slayer's Duellum} gives each time the reputation bar fills again after the reputation is at its maximum. About 26% of the troves have the mount; the others may bring the same pet again and again." },
    [2767] = { year = 2026, -- Contained Stormarion Defender
        text = "Two caches can have it, a few in every hundred: {item:268485|Victorious Stormarion Pinnacle Cache}, the weekly one for finishing {quest:90962|Stormarion Assault}, and {item:260979|Victorious Stormarion Cache}, the one of its world quest. The world quest only shows up for a character that has finished the event once." },
    [2772] = { year = 2026, -- Blessed Amani Burrower, Amani Sunfeather (Abundance vendor)
        text = "The journal says 1,600 {currency:3377|Unalloyed Abundance}, but {npc:241928|Chel the Chip} charges 6,400." },
    [2775] = { year = 2026, -- Amani Sharptalon, Witherbark Pango (Zul'Aman rares)
        text = "Any rare of {map:2437|Zul'Aman} can drop it, each with a chance of about 0.1%. A rare gives loot once a day per character, so players repeat the round on other characters. Reports go from a few kills to more than 2,000." },
    [2778] = { year = 2026, -- Ancestral War Bear
        text = "The Honored Warrior's Cache is inside the base of the tree at 47.0, 82.4 of {map:2437|Zul'Aman}. Click it first: only then do the four Honored Warrior's Urns answer. Each urn calls a guardian that drops one token: {npc:255171|Nalorakk's Chosen} at 32.6, 83.5, {npc:255232|Halazzi's Chosen} at 34.5, 33.4, {npc:255233|Jan'alai's Chosen} at 54.7, 22.3 and {npc:255231|Akil'zon's Chosen} at 51.5, 84.9. With the four tokens, go back to the cache." },
    [2779] = { year = 2026, -- Witherbark Warbear Mother
        text = "Take 6 {item:242639|Practically Pork} with you (auction house, or the beasts outside) into the ritual site {map:2585|Broken Throne}, on tier 2 or higher. The Lost Bear Cub is hidden beside a tree at 55.8, 49.5, on a ledge you reach by jumping down: feed him 1 and he becomes the pet {item:269836|Chubs}. Summon Chubs at the Chewed Meat at 56.0, 38.5 and an angry warbear comes. Beat her; she turns friendly, and you feed her the other 5." },
    [2786] = { year = 2026, -- Hexed Vilefeather Eagle
        text = "The Abandoned Ritual Skull is in a small cave of {map:2437|Zul'Aman}, at 44.7, 44.1 (entrance at 44.2, 43.5), and asks for 1,000 {item:259361|Vile Essence}, dropped by the creatures of the elite area around 45.8, 40.2. Players count 6 to 7 hours.\nWhat makes it bearable: take {quest:91838|De Vile Diminished}, {quest:91836|Respect de Totem} and {quest:91835|Send Dem Home} there and do NOT hand them in. While they are in the log you keep an extra action button with a buff, and each {npc:248775|Wild Guardian} killed gives a second one. Since April 2026 each stacks only 3 times, not 10, and lasts 3 minutes: it helps less, and alone it is harder than older reports say. Turn off any addon that hands quests in by itself. Who has done those quests does it on another character." },
    [2790] = { year = 2026, -- Insatiable Shredclaw
        text = "The cave is in the south of {map:2405|Voidstorm}, entrance at 48.9, 78.4. Inside, broken eggs make a maze of lightning circles; being hit sends you back to the entrance. The Final Clutch of Predaxas is at the end. Players say a circle stops hurting a little before it vanishes, and that a trail of wind on the ground shows the way." },
    [2827] = { year = 2026, -- Augmented Stormray, Sanguine Harrower (Voidstorm rares)
        text = "Any rare of {map:2405|Voidstorm} can drop it, each with a chance of about 0.1%. A rare gives loot once a day per character, so players repeat the round on other characters, level 80 ones included. Reports go from the first kill to more than 2,000." },
    [2829] = { year = 2026, -- Lab-Grown Stormray
        text = "{achievement:62385|Staring Into The Void} asks for 7 {currency:3400|Uncontaminated Void Sample}: 1 at the start, then each week 1 from the weekly quest of {npc:248328|Void Researcher Anomander}, beside the console, and 1 from the weekly cache of {quest:90962|Stormarion Assault}. About 3 weeks. If the mount does not come with the achievement, look in the mail, or use Wings of the Void in the spellbook: it puts the item in your bag, wherever you are." },
    [2839] = { year = 2026, -- Delver's Arcane Golem
        text = "Inside the delve Gnarldor Isle, on any tier: the Sturdy Chest at 60.4, 68.1. The delve has three Sturdy Chests; the mount came from this one." },
    [2913] = { year = 2026, -- Vivid Chloroceros, Elder Glowmite (Luminous Dust)
        text = "{currency:3385|Luminous Dust} comes from the Glowing Moths scattered over {map:2413|Harandar}, 120 in all. They open in three groups of 40, at Renown 1, 5 and 6 with {faction:2704|Hara'ti}; the map only marks each group later, at Renown 2, 6 and 11. The player who mapped them advises reaching Renown 9 before hunting." },
    [2950] = { year = 2026, -- Luminous Sporeglider
        text = "It is made by combining 4 {item:269245|Delicious Sporesnack}. {npc:254176|Rotmire} gives one per week to the whole account, on any difficulty: four weeks at least." },
    [2961] = { year = 2026, -- Void-Corrupted Hex Eagle
        text = "In the ritual site {map:2585|Broken Throne}, on tier 2 or higher. One of the four skulls around the ritual circle at 50.6, 47.3 has no candle: pick up the Misplaced Ritual Candle under the tree at 51.5, 47.8 and put it on the skull at the north-east of the circle. Then click the candles in the middle and kill the eagle that comes: it drops the mount. If three eaglets come instead, the candle was not in place." },
    [2964] = { year = 2026, -- Void-Touched Snapdragon
        text = "In the ritual site {map:2594|Daggerspine Point}, on any tier, up to 2 Washed Up Kelp appear per run, out of 8 spots along the shores. Clicking one calls creatures and, with a small chance, the Void-Touched Snapdragon, which drops the mount. Players check the kelp, leave the instance and enter again, without doing the ritual. The {item:228966|Starry-Eyed Goggles} make the kelp easier to see. Reports go from 25 attempts to about 70 kelps clicked." },
    [2965] = { year = 2026, -- Void-Corrupted Lynx
        text = "This mount is crafted, not looted. {item:270058|Rope Lynx Harness} is made with Midnight Leatherworking (90) from 1 {item:272392|Broken Lynx Leash}, 40 {item:236950|Mote of Primal Energy}, 1 {item:244634|Infused Scalewoven Hide} and 2 {item:244636|Sin'dorei Armor Banding}.\nThe leash is the part you loot: the ritual chest at the end of a ritual site gives it in 1.5% of the openings at {map:2585|Broken Throne} and 0.5% at {map:2594|Daggerspine Point}, on any tier. Players report it only after Renown 8 with the {faction:2792|Ritual Sites}. It binds to you.\nThe {item:272391|Pattern: Rope Lynx Harness} comes from the same chest at Broken Throne (0.3%) and can be bought at the auction house. Without leatherworking, send the leash in a crafting order to a leatherworker who has the pattern." },
    [2980] = { year = 2026, -- Spirit of Tok'jara
        text = "At Renown 10 with {faction:2772|Zul'jarra's Forces}, {npc:264611|Du'gal} (50.5, 63.9 in {map:2509|Vaults of Atal'Utek}) starts a chain of 6 quests, one per day, from {quest:96267|Ancestral Gems} to {quest:96305|The Innocent Essence}, which gives the mount. Six days at least, and the chain is of the character that started it." },
    [3005] = { year = 2026, -- Lindormi's six mounts (Timelost Saddle)
        text = "In Season 1 of Midnight, {item:275436|Timelost Saddle} came with {achievement:63097|Midnight Keystone Myth: Season 1}, 3,400 of Mythic+ rating, and expired when the season ended. Each saddle bought one of the mounts {npc:197711|Lindormi} sells, the player choosing which." },
    [3006] = { year = 2026, -- Lindormi's six mounts (Timelost Saddle)
        text = "In Season 1 of Midnight, {item:275436|Timelost Saddle} came with {achievement:63097|Midnight Keystone Myth: Season 1}, 3,400 of Mythic+ rating, and expired when the season ended. Each saddle bought one of the mounts {npc:197711|Lindormi} sells, the player choosing which." },
    [3007] = { year = 2026, -- Lindormi's six mounts (Timelost Saddle)
        text = "In Season 1 of Midnight, {item:275436|Timelost Saddle} came with {achievement:63097|Midnight Keystone Myth: Season 1}, 3,400 of Mythic+ rating, and expired when the season ended. Each saddle bought one of the mounts {npc:197711|Lindormi} sells, the player choosing which." },
    [3008] = { year = 2026, -- Lindormi's six mounts (Timelost Saddle)
        text = "In Season 1 of Midnight, {item:275436|Timelost Saddle} came with {achievement:63097|Midnight Keystone Myth: Season 1}, 3,400 of Mythic+ rating, and expired when the season ended. Each saddle bought one of the mounts {npc:197711|Lindormi} sells, the player choosing which." },
